function loadDemo(){try{const data=JSON.parse(localStorage.getItem('SGI_RC8_DEMO_STATE')||'null');if(data&&data.version===8){for(const k of demoStoreKeys)if(Array.isArray(data[k])){if(Object.hasOwn(state,k))state[k]=data[k];else extra[k]=data[k];}extra.records=extra.records||demoSeed();}}catch(e){console.warn('Estado de demo anterior ignorado',e)}}
function saveDemo(){try{const data={version:8};for(const k of demoStoreKeys)data[k]=Object.hasOwn(state,k)?state[k]:extra[k];localStorage.setItem('SGI_RC8_DEMO_STATE',JSON.stringify(data));}catch(e){console.warn('Sem persistência demonstrativa',e)}}
const roleLabels={paciente:'Paciente',colaborador:'Colaborador',profissional:'Profissional de saúde',prestador:'Prestador de serviço',fornecedor:'Fornecedor',representante:'Representante',responsavel:'Responsável legal',pagador:'Responsável financeiro',convenio:'Convênio / operadora',parceiro:'Parceiro',outro:'Outro vínculo'};
