 lancamento:[['Natureza da operação','Entrada, saída e transferência possuem regras diferentes.'],['Valor e data','Diferencie data da operação, competência, vencimento e pagamento real.'],['Pessoa, serviço e profissional','Identifique referências necessárias sem inventar IDs.'],['Conciliação','Pix informado não confirma depósito; crédito Stone exige conferência.'],['Aprovação','Solicitações da Recepção sempre dependem da Dra. Simone.']],
