function trainingView(){let steps=helpGuides[extra.guideId]||helpGuides.cadastro;extra.guideIndex=Math.max(0,Math.min(extra.guideIndex,steps.length-1));let [title,description]=steps[extra.guideIndex];return head('DOCUMENTOS / TREINAMENTO','Passo a Passo do Sistema','Ajuda voluntária por função. No aplicativo real, só aparecerão tours autorizados.')+box('Escolha a tarefa',`<div class="fields">${select('Treinamento','training-type',Object.entries({cadastro:'Cadastro de pessoa',lancamento:'Recepção — Lançamento financeiro',orcamento:'Documentos — Orçamento',estoque:'Estoque — Registrar aparelho',governanca:'Governança — Pedido de acesso'}),extra.guideId)}</div>`)+`<div class="tour-view"><div class="tour-progress">Etapa ${extra.guideIndex+1} de ${steps.length}<div class="tour-track"><div style="width:${(extra.guideIndex+1)/steps.length*100}%"></div></div></div><h3>${esc(title)}</h3><p>${esc(description)}</p><div class="notice">Nenhuma informação real deve ser usada durante demonstrações. O tour não salva registros automaticamente.</div><div class="row space">${btn('Voltar','tour-back','small',extra.guideIndex===0?'disabled':'')}${btn(extra.guideIndex===steps.length-1?'Reiniciar':'Próximo campo','tour-next','primary')}</div></div>`+box('Acesso rápido',`<p>O treinamento permanecerá no módulo Documentos e no FAQ global, com atalhos contextuais dentro dos aplicativos licenciados.</p>`)}
function contingencyView(){const rows=extra.contingency.map(r=>`<div class="task"><div class="detail"><b>${esc(r.code)} · ${esc(r.type)}</b><p>${esc(r.person)} · ${esc(r.when)} · ${esc(r.notes)}</p></div><div class="cell-actions">${badge(r.status)}${r.status==='em conferência'?btn('Conciliar como histórico','contingency-approve:'+r.code,'small'):''}</div></div>`).join('');return head('DOCUMENTOS / CONTINUIDADE','Kit de Contingência','Registros mínimos para operação manual e retorno sem duplicar fila ou caixa.',btn('Baixar kit .xlsx','kit-xlsx','primary')+btn('Imprimir ficha','print:contingencia'))+box('Registrar ficha manual',`<form id="contingency-form"><div class="fields">${field('Código único na ficha','code','text','','required placeholder="Ex.: CTG-001"')}${select('Tipo de ocorrência','type',[['cadastro','Cadastro'],['fila','Chegada / fila'],['atendimento','Atendimento concluído'],['entrada','Entrada financeira'],['saida','Saída financeira'],['documento','Documento'],['estoque','Movimentação equipamento']])}${field('Identificação mínima / referência','person','text','','required')}${field('Quando ocorreu','when','datetime-local','2026-11-19T10:00','required')}${textArea('O que aconteceu?','notes','','Não insira dados reais nesta demo.')}</div><div class="formfoot"><button class="btn primary" type="submit">Adicionar à conferência</button></div></form>`)+box('Retomada assistida',`<p>Importe o arquivo do kit oficial (.xlsx) após preencher no Excel, ou cadastre cada ficha no formulário acima. As linhas ficam pendentes de revisão; nunca geram pagamento ou fila automaticamente.</p><div class="field"><label for="contingency-xlsx">Importar kit preenchido (.xlsx)</label><input id="contingency-xlsx" type="file" accept=".xlsx"></div>${rows||'<div class="empty">Nenhuma ficha fictícia registrada.</div>'}`)+note('Código repetido é recusado. O kit funciona em papel durante indisponibilidade. Somente arquivos .xlsx do modelo do Kit SGI são aceitos nesta demo; OCR e sincronização automática não estão ativos.')}
async function importKitXLSX(file){if(!file||file.size>2_000_000)throw Error('Arquivo deve ter até 2 MB.');const bytes=new Uint8Array(await file.arrayBuffer()),view=new DataView(bytes.buffer);let pos=0,xml='';const dec=new TextDecoder();while(pos+30<bytes.length){if(view.getUint32(pos,true)!==0x04034b50)break;let method=view.getUint16(pos+8,true),size=view.getUint32(pos+18,true),len=view.getUint16(pos+26,true),more=view.getUint16(pos+28,true);let path=dec.decode(bytes.slice(pos+30,pos+30+len)),start=pos+30+len+more;if(path==='xl/worksheets/sheet1.xml'){if(method!==0)throw Error('Utilize o modelo Excel fornecido pelo kit SGI, sem compressão adicional.');xml=dec.decode(bytes.slice(start,start+size));break;}pos=start+size;}if(!xml)throw Error('Arquivo não corresponde ao modelo de kit do SGI.');const root=new DOMParser().parseFromString(xml,'application/xml');if(root.querySelector('parsererror'))throw Error('Planilha inválida.');const rows=[...root.querySelectorAll('row')].map(row=>[...row.querySelectorAll('c')].map(cell=>cell.textContent.trim()));let heads=rows.shift()||[];if(!['codigo','tipo','data_hora_real','referencia','responsavel','situacao'].every(h=>heads.includes(h)))throw Error('Colunas do kit não correspondem ao modelo.');let imported=0,dups=0;for(const vals of rows.slice(0,150)){let r=Object.fromEntries(heads.map((h,i)=>[h,vals[i]||'']));let code=String(r.codigo||'').trim();if(!code)continue;if(extra.contingency.some(x=>x.code.toLowerCase()===code.toLowerCase())){dups++;continue;}extra.contingency.unshift({code,type:r.tipo||'documento',when:r.data_hora_real||'',person:r.referencia||'',notes:`${r.situacao||''} · ${r.observacoes_minimas||''} · Registro manual de ${r.responsavel||'responsável não indicado'}`,status:'em conferência'});imported++;}audit('Kit Excel demonstrativo analisado: '+imported+' fichas; '+dups+' repetidas');render();toast(imported+' ficha(s) para conferência. '+dups+' código(s) duplicado(s) ignorado(s).');}
function marketingView(){if(state.page==='editor')return marketingEditor();if(state.page==='analise')return marketingAnalytics();if(state.page==='planejamento')return head('MARKETING / PLANEJAMENTO','Calendário editorial','Organize publicações e campanhas sem criar envios automáticos.',btn('＋ Planejar publicação','modal:marketing-post','primary'))+box('Planejamento',extra.marketing.map(x=>`<div class="task"><div class="detail"><b>${esc(x.title)}</b><p>${dateBR(x.date)} · ${esc(x.type||'post')} · ${esc(x.notes||'')}</p></div>${badge('planejado')}</div>`).join('')||'<div class="empty">Adicione uma publicação fictícia para demonstrar o calendário.</div>');return head('MARKETING / INÍCIO','Marketing e Redes','Crie peças com a identidade da clínica e avalie métricas informadas manualmente.',btn('Criar arte','nav:editor','primary'))+`<div class="grid">${[['Editor de fotos','nav:editor','Corte, zoom, marca e PNG'],['Análise de redes','nav:analise','Insights de dados conferidos'],['Calendário de conteúdo','nav:planejamento','Publicações e campanhas'],['Assistente de Marketing','marketing-help','Dicas sob demanda, sem mensagens espontâneas']].map(([title,act,desc])=>`<div class="card c6"><h3>${title}</h3><p>${desc}</p>${btn('Abrir',act,'small')}</div>`).join('')}</div>`}
function marketingEditor(){return head('MARKETING / DESIGN','Editor visual de publicações','Foto local, moldura, logotipo e exportação PNG. Nada é transmitido.',btn('Precisa de ajuda?','marketing-help'))+`<div class="marketing-layout"><section class="card"><h2>Personalizar peça</h2><div class="fields">${select('Modelo','marketing-style',[['servico','Serviço em destaque'],['dica','Dica educativa'],['mosaico','Moldura editorial'],['reels','Capa vertical para Reels/Stories']],extra.marketingDesign)}<div class="field full"><label for="marketing-image">Foto local (opcional)</label><input type="file" id="marketing-image" accept="image/png,image/jpeg,image/webp"><small>Prévia fica somente neste dispositivo.</small></div>${field('Título da arte','marketing-text','text',extra.marketingText)}${field('Zoom da foto (%)','marketing-zoom','range',extra.marketingZoom,'min="50" max="260" step="5"')}${field('Posição horizontal','marketing-x','range',extra.marketingX,'min="-100" max="100"')}${field('Posição vertical','marketing-y','range',extra.marketingY,'min="-100" max="100"')}</div><div class="formfoot">${btn('Atualizar prévia','marketing-draw','primary')}${btn('Exportar PNG','marketing-export')}</div>${note('Não envie fotos de pacientes sem autorização específica e conferência das regras profissionais aplicáveis.')}</section><section class="card"><h2>Prévia da composição</h2><canvas id="marketing-canvas" width="540" height="675" class="marketing-canvas" aria-label="Prévia da arte de marketing">Seu navegador não suporta canvas.</canvas><p class="tiny">O enquadramento é controlado pelos sliders. Modelo Reels usa proporção vertical.</p></section></div>`}
const marketingLogo=new Image();marketingLogo.src='./logo.png';marketingLogo.onload=()=>{if($('#marketing-canvas'))drawMarketing()};
function drawMarketing(){const cvs=$('#marketing-canvas');if(!cvs)return;const isReels=extra.marketingDesign==='reels';cvs.width=540;cvs.height=isReels?960:675;const g=cvs.getContext('2d');const h=cvs.height;g.fillStyle='#edf6f5';g.fillRect(0,0,540,h);g.fillStyle='#0c5c65';g.fillRect(0,0,540,21);g.fillRect(0,h-150,540,150);if(extra.imageUrl&&extra.imageEl?.complete&&extra.imageEl?.naturalWidth){let img=extra.imageEl,sz=Math.max(540/img.width,(h-120)/img.height)*extra.marketingZoom/100,iw=img.width*sz,ih=img.height*sz;g.save();g.beginPath();g.rect(15,21,510,h-171);g.clip();g.drawImage(img,(540-iw)/2+extra.marketingX*2,(h-ih)/2+extra.marketingY*2,iw,ih);g.restore()}else{g.fillStyle='#badbdc';g.fillRect(15,30,510,h-186);g.fillStyle='#286c73';g.font='bold 19px system-ui';g.textAlign='center';g.fillText('Adicione sua própria foto',270,h/2)}g.textAlign='left';g.fillStyle='#ffffff';g.font='bold 29px system-ui';const words=(extra.marketingText||'Saúde auditiva').split(' ');let lines=[],line='';for(const w of words){if((line+' '+w).length>30){lines.push(line);line=w}else line+=(line?' ':'')+w;}lines.push(line);lines.slice(0,2).forEach((s,i)=>g.fillText(s.slice(0,30),27,h-100+i*36));g.font='14px system-ui';g.fillText('CLÍNICA ÁUDIO S.A. · PEÇA DEMONSTRATIVA',27,h-24);g.strokeStyle='#52b9b5';g.lineWidth=5;g.strokeRect(15,31,510,h-198);if(marketingLogo.complete&&marketingLogo.naturalWidth){g.fillStyle='#ffffff';g.fillRect(446,34,76,76);g.drawImage(marketingLogo,450,38,68,68)}}
function captureMarketingControls(){const st=$('#marketing-style'),txt=$('#f-marketing-text'),zoom=$('#f-marketing-zoom'),xx=$('#f-marketing-x'),yy=$('#f-marketing-y');if(st)extra.marketingDesign=st.value;if(txt)extra.marketingText=txt.value;if(zoom)extra.marketingZoom=Number(zoom.value)||100;if(xx)extra.marketingX=Number(xx.value)||0;if(yy)extra.marketingY=Number(yy.value)||0;}
function marketingAnalytics(){return head('MARKETING / REDES','Análise de redes sociais','Registre métricas do Instagram Insights sem conexão direta à Meta.',btn('＋ Inserir métricas','modal:social','primary')+btn('Ajuda de marketing','marketing-help'))+`<div class="grid">${[['Período',extra.social.at(-1)?.period||'—'],['Alcance',String(extra.social.at(-1)?.reach??0)],['Visualizações',String(extra.social.at(-1)?.views??0)],['Interações',String(extra.social.at(-1)?.engagement??0)]].map(([k,v])=>`<div class="card c3 stat"><div class="label">${k}</div><div class="value">${esc(v)}</div><small>Fonte declarada · exemplo</small></div>`).join('')}</div>`+box('Orientador de Marketing',`<p>Confira a evolução das métricas apenas entre períodos e definições comparáveis. Interações não comprovam agendamentos ou receita. Para melhorar os vídeos: luz à frente, câmera na altura dos olhos, ambiente silencioso e informação de saúde revisada.</p>`)+box('Histórico informado',extra.social.map(x=>`<div class="task"><div class="detail"><b>${esc(x.period)} · Alcance ${x.reach}</b><p>Visualizações ${x.views} · Interações ${x.engagement} · Origem ${esc(x.source)}</p></div></div>`).join(''))+note('Prints podem ser anexados no fluxo futuro com conferência humana/OCR. Esta demo não acessa Instagram, não extrai dados de prints e não publica posts.')}
