function printDocument(type){const popup=window.open('','_blank','width=900,height=850');if(!popup){toast('Permita pop-ups para impressão.');return}let title=type==='contingencia'?'Ficha de Contingência':type==='teste'?'Teste de Impressão':type.startsWith('ORC')?'Orçamento '+type:'Documento demonstrativo';let content=type==='contingencia'?['Código de contingência: ______________','Data e hora do acontecimento: ______________','Tipo de ocorrência: ______________','Referência administrativa: ______________','Profissional/responsável pelo registro: ______________','Situação observada: ______________','Valor/meio (se pertinente): ______________','Observações mínimas: ______________','Conferido por: ______________']:type.startsWith('ORC')?(()=>{let b=extra.budgets.find(x=>x.id===type);return b?[`Cliente: ${entityName(b.person)}`,...b.items.map(i=>`${i.label} — ${i.qty} × ${brl(i.amount)}`),`Desconto: ${brl(b.discount)}`,`TOTAL: ${brl(b.total)}`,`Condições: ${b.terms}`,`Estado: ${b.status} · Versão ${b.version}`]:['Orçamento não localizado']})():['Modelo fictício sem validade clínica, comercial ou jurídica.'];popup.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font:15px Arial;color:#143d49;margin:45px}header{border-bottom:4px solid #168d88;padding-bottom:20px}h1{font-size:22px}li{margin:17px 0;border-bottom:1px solid #ccc;padding:7px}footer{margin-top:45px;color:#6e7a7d;font-size:11px}@media print{body{margin:15mm}}</style></head><body><header><h2>CLÍNICA ÁUDIO S.A.</h2><p>DEMONSTRAÇÃO · DOCUMENTO FICTÍCIO</p></header><h1>${esc(title)}</h1><ul>${content.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><footer>Protótipo SGI · Documento sem validade operacional. Não utilizar com dados reais.</footer><script>window.onload=()=>window.print();<\/script></body></html>`);popup.document.close()}
function exportContingencyXLSX(){const headers=['codigo','tipo','data_hora_real','referencia','responsavel','situacao','valor_quando_pertinente','observacoes_minimas'];const rows=[{codigo:'CTG-DEMO-001',tipo:'entrada',data_hora_real:'2026-11-19 10:00',referencia:'PAC-001',responsavel:'Recepção Exemplo',situacao:'pendente de conferência',valor_quando_pertinente:'R$ 220,00',observacoes_minimas:'Exemplo fictício'}];download(createXLSX(headers,rows,'Contingência'),'SGI_Kit_Contingencia_MODELO_DEMO.xlsx')}
function createXLSX(headers,rows,sheetname='Modelo'){const entries=[['[Content_Types].xml',`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>`],['_rels/.rels',`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`],['xl/workbook.xml',`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${xesc(sheetname)}" sheetId="1" r:id="rId1"/></sheets></workbook>`],['xl/_rels/workbook.xml.rels',`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`],['xl/worksheets/sheet1.xml',sheetXML(headers,rows)]];return zipStore(entries)}

function render(){if(sessionStorage.getItem('SGI_RC8_DEV_LOGIN')!=='yes'){$('#root').innerHTML=loginView();return;}saveDemo();document.documentElement.dataset.theme=state.theme;let nav=state.app==='home'?[]:menus[state.app]||[];if(state.app==='finance'&&!safeFinanceAccess())nav=[['lancamentos','Meus lançamentos'],['novo','Novo lançamento']];let showNav=state.app!=='home';const common=`<div class="topbar"><div class="brand"><div class="brandmark">A</div><div><b>SGI audiosa.app</b><small>Clínica Áudio S.A. · Protótipo RC8 DEV</small></div></div><div class="topactions"><span class="badge dark desktop-only">DEMO · SEM BANCO</span><select id="role" aria-label="Simular perfil" title="Troca de perfil é apenas simulação">${options(Object.entries(profileNames),state.role)}</select><button class="btn small" data-act="theme" title="Alternar tema">${state.theme==='light'?'☾':'☀'}</button><button class="btn small" data-act="notices" title="Avisos e tarefas">🔔</button>${state.role==='dev'?btn('🧪 Laboratório','open:lab','small'):''}${btn('Suporte','support','small')}${btn('Sair','logout','small')}${showNav?btn('← Área de Trabalho','home','small'):''}</div></div>`;
const navHTML=showNav?`<aside class="sidebar"><h4>${esc(modules.find(m=>m.id===state.app)?.name||'SGI')}</h4>${nav.map(([id,name])=>`<button class="navbtn ${state.page===id?'active':''}" data-act="nav:${id}"><span class="nav-ic">${state.page===id?'▰':'◇'}</span>${esc(name)}</button>`).join('')}<h4>RETORNO</h4><button class="navbtn" data-act="home">⌂ &nbsp;Área de Trabalho</button><p style="padding:12px;font-size:11px;color:#b4d3db">Demonstração: nenhuma informação é enviada para a clínica, bancos, pacientes ou fornecedores.</p></aside>`:`<aside class="sidebar workspace-sidebar"><h4>ÁREA DE TRABALHO</h4><button class="navbtn active" data-act="home">⌂ &nbsp; Início</button><button class="navbtn" data-act="home-modules">⊞ &nbsp; Módulos</button><button class="navbtn" data-act="notices">♧ &nbsp; Avisos</button><button class="navbtn" data-act="support">? &nbsp; Ajuda e Suporte</button><button class="navbtn" data-act="settings">⚙ &nbsp; Ajustes</button><h4>APLICATIVOS</h4>${modules.map(m=>`<button class="navbtn" data-act="open:${m.id}">${m.icon} &nbsp; ${esc(m.name)}</button>`).join('')}</aside>`;
let content='';try{content=state.app==='home'?launcher():state.app==='finance'?financeView():state.app==='patients'?patientView():state.app==='agenda'?agendaView():state.app==='documents'?documentsView():state.app==='cadastro'?cadastroView():state.app==='marketing'?marketingView():state.app==='support'?supportView():state.app==='stock'?stockView():state.app==='gov'?govView():state.app==='hr'?hrView():state.app==='lab'?renderLab():launcher()}catch(err){console.error(err);content=note('Falha no desenho da tela demonstrativa: '+esc(err.message),'danger')}
$('#root').innerHTML=`<div class="shell">${common}<div class="layout">${navHTML}<main class="content ${showNav?'':'launch-content'}" id="main">${state.feedback?`<div class="action-feedback" role="status"><b>${esc(state.feedback.title)}</b><span>${esc(state.feedback.body)}</span><button class="btn small" data-act="dismiss-feedback">Fechar</button></div>`:''}${content}<footer class="foot">SGI audiosa.app · RC8 · DEMONSTRAÇÃO — SEM BANCO · Sem autenticação real, banco, envio externo, assinatura válida ou operações reais. Os módulos futuros estão acessíveis somente para avaliação.</footer></main></div>${showNav?`<div class="mobile-nav"><button data-act="home"><span>⌂</span>Início</button><button class="${state.page===nav[0]?.[0]?'current':''}" data-act="nav:${nav[0]?.[0]||'resumo'}"><span>▤</span>${esc(nav[0]?.[1]||'Resumo')}</button><button data-act="mobile-menu"><span>☷</span>Mais</button><button data-act="notices"><span>♢</span>Avisos</button></div>`:''}</div>`;if(state.app==='marketing'&&state.page==='editor')requestAnimationFrame(drawMarketing);}
function launcher(){
 const items=modules.map(m=>`<button class="workspace-module" data-act="open:${m.id}"><span class="ws-icon">${m.icon}</span><span class="ws-text"><b>${esc(m.name)}</b><small>${esc(m.note)}</small></span><span class="ws-arrow">↗</span></button>`).join('');
 const pending=state.tx.filter(t=>t.status==='aguardando validacao').length,obligations=state.obligations.filter(o=>o.status==='previsto').length;
 const attention=state.role==='recepcao'?`<div class="task"><div class="detail"><b>Minhas solicitações financeiras</b><p>Acompanhe rascunhos e registros enviados à validação.</p></div>${btn('Abrir','open:finance','small')}</div>`:state.role==='profissional'||state.role==='rh'?`<div class="task"><div class="detail"><b>Atividades autorizadas</b><p>Selecione um aplicativo demonstrativo para conhecer seu fluxo.</p></div></div>`:`<div class="task"><div class="detail"><b>${pending} lançamento(s) aguardando validação</b><p>Solicitações demonstrativas da Recepção</p></div>${btn('Conferir','open:finance','small')}</div><div class="task"><div class="detail"><b>${obligations} parcela(s) pendente(s)</b><p>Compromissos previstos na demonstração</p></div>${btn('Ver','open:finance','small')}</div>`;
 return `<header class="ws-heading"><div><span class="eyebrow">CLÍNICA ÁUDIO S.A. · ÁREA DE TRABALHO</span><h1>Seus aplicativos</h1><p>Ambientes independentes, reunidos em um só lugar.</p></div><span class="env-tag">DEMONSTRAÇÃO · SEM BANCO</span></header><section class="workspace-grid" aria-label="Aplicativos do SGI">${items}</section><div class="ws-secondary"><section class="card"><div class="cardheader"><div><h2>Fila de atenção</h2><p class="tiny">Somente exemplos do perfil selecionado</p></div></div>${attention}</section><section class="card"><div class="cardheader"><div><h2>Comunicados da clínica</h2><p class="tiny">Informações internas da equipe</p></div></div>${state.notices.slice(0,2).map(n=>`<div class="task"><div class="detail"><b>${esc(n.title)}</b><p>${esc(n.body)}</p></div></div>`).join('')}<div class="row">${btn('Ver avisos','notices')}${permissions()?btn('Novo aviso','modal:notice'):''}</div></section></div>`;
}

function monthOf(date){return String(date||'').slice(0,7)}
function periodTransactions(){return state.tx.filter(t=>(state.biMonth==='all'||monthOf(t.date)===state.biMonth)&&t.status!=='aguardando validacao'&&t.status!=='rascunho'&&t.kind!=='transferencia')}
function biMoney(t){return Number(t.net||0)}
function financeBI(){
 const transactions=periodTransactions(),approved=transactions.filter(t=>['previsto','liquidado'].includes(t.status));
 const incoming=approved.filter(t=>t.kind==='entrada'),outgoing=approved.filter(t=>t.kind==='saida');
 const cashTx=approved.filter(t=>t.status==='liquidado');
 const incomeCash=cashTx.filter(t=>t.kind==='entrada').reduce((a,t)=>a+biMoney(t),0),expenseCash=cashTx.filter(t=>t.kind==='saida').reduce((a,t)=>a+biMoney(t),0);
 const probableIncoming=approved.filter(t=>t.kind==='entrada'&&t.status==='previsto').reduce((a,t)=>a+biMoney(t),0);
 const probableOutgoing=approved.filter(t=>t.kind==='saida'&&t.status==='previsto'&&!t.planPending).reduce((a,t)=>a+biMoney(t),0)+state.obligations.filter(o=>o.status==='previsto'&&(state.biMonth==='all'||monthOf(o.due)===state.biMonth)).reduce((a,o)=>a+Number(o.value||0),0);
 const revenues=incoming.reduce((a,t)=>a+biMoney(t),0),costs=outgoing.reduce((a,t)=>a+biMoney(t),0)+state.obligations.filter(o=>o.status==='previsto'&&o.origin==='modal'&&(state.biMonth==='all'||monthOf(o.due)===state.biMonth)).reduce((a,o)=>a+Number(o.value||0),0);
 const notClassified=approved.filter(t=>!t.category&&t.kind==='saida').length;
 return {transactions,approved,incoming,outgoing,incomeCash,expenseCash,probableIncoming,probableOutgoing,revenues,costs,notClassified,estimatedResult:revenues-costs,liquidity:probableIncoming-probableOutgoing,cash:clinicCash()};
}
function monthlyTrend(){const data={};for(const t of state.tx){if(!['previsto','liquidado'].includes(t.status)||t.kind==='transferencia')continue;const month=monthOf(t.date);if(!/^\d{4}-\d{2}$/.test(month))continue;data[month]??={month,income:0,out:0};if(t.kind==='entrada')data[month].income+=biMoney(t);else if(!t.planPending)data[month].out+=biMoney(t)}return Object.values(data).sort((a,b)=>a.month.localeCompare(b.month)).slice(-7)}
function orientadorBI(x){
 const hints=[];const waiting=state.tx.filter(t=>t.status==='aguardando validacao').length;
 const withoutTariff=state.stone.filter(t=>t.fee===null).length;
 const divergences=state.stone.filter(t=>t.status==='divergencia').length;
 if(waiting&&permissions())hints.push({label:'Solicitações para revisar',msg:`${waiting} lançamento(s) aguardam validação. Antes de reconhecer efeitos financeiros, confira origem e comprovantes.`,target:'lancamentos',priority:1});
 if(withoutTariff||divergences)hints.push({label:'Conciliação de cartões',msg:`${withoutTariff} taxa(s) pendentes e ${divergences} divergência(s) Stone. Não trate o previsto como crédito confirmado.`,target:'stone',priority:1});
 if(x.liquidity<0)hints.push({label:'Acompanhe o fluxo futuro',msg:`A diferença entre recebimentos e pagamentos previstos é ${brl(x.liquidity)}. Confira vencimentos e entradas esperadas.`,target:'compromissos',priority:1});
 if(x.notClassified)hints.push({label:'Dados a classificar',msg:`${x.notClassified} despesa(s) não têm categoria informada. Isso limita análises de custos por tipo.`,target:'relatorios',priority:2});
 if(x.estimatedResult<0)hints.push({label:'Resultado gerencial estimado',msg:'As despesas e obrigações demonstrativas atribuídas ao período superam as entradas. Investigue os registros antes de concluir que existe prejuízo.',target:'analises',priority:2});
 if(!hints.length)hints.push({label:'Como ler os resultados',msg:'Compare realizado, previsto e resultado. Use “Entender cálculo” para conferir os registros e as limitações da informação.',target:'analises',priority:3});
 return hints.sort((a,b)=>a.priority-b.priority).slice(0,3);
}
function biMonthlyChart(){const trend=monthlyTrend();if(!trend.length)return '<div class="empty">Sem lançamentos suficientes para construir o gráfico.</div>';const mx=Math.max(1,...trend.flatMap(x=>[x.income,x.out]));return `<div class="bi-chart" role="group" aria-label="Selecionar período no gráfico">${trend.map(x=>`<button class="bi-chart-col ${state.biMonth===x.month?'selected':''}" type="button" data-act="bi-month:${x.month}" title="${x.month}: receitas ${brl(x.income)}, despesas ${brl(x.out)}"><span class="bi-plot"><i style="height:${Math.max(3,Math.round(100*x.income/mx))}%"></i><i style="height:${Math.max(3,Math.round(100*x.out/mx))}%"></i></span><span>${esc(x.month.slice(5))}/${esc(x.month.slice(2,4))}</span></button>`).join('')}</div><div class="bi-legend"><span><i class="in"></i> Receitas identificadas</span><span><i class="out"></i> Despesas identificadas</span></div>`}
function formulaDrawer(id){const x=financeBI();let templates={
 caixa:['Saldo do caixa demonstrativo',`Saldos iniciais de contas próprias (${brl(state.accounts.filter(a=>a.kind!=='personal').reduce((a,b)=>a+b.opening,0))}) + recebimentos confirmados − pagamentos confirmados + transferências internas (efeito consolidado zero).`,`Saldo de demonstração: ${brl(x.cash)}. Não equivale a extrato bancário certificado.`],
 fluxo:['Fluxo líquido previsto',`Entradas previstas (${brl(x.probableIncoming)}) − saídas previstas e parcelas abertas (${brl(x.probableOutgoing)}).`,`Diferença: ${brl(x.liquidity)}. Não é garantia de disponibilidade futura.`],
 resultado:['Resultado gerencial estimado',`Entradas atribuídas ao período (${brl(x.revenues)}) − despesas atribuídas disponíveis (${brl(x.costs)}).`,`Resultado: ${brl(x.estimatedResult)}. Provisório: faltam classificações, confirmação da competência e possível tratamento de custos fixos e repasses; não é DRE formal.`]
 };const [title,rule,limit]=templates[id]||templates.fluxo;return `<div class="formula"><h3>${title}</h3><p>${rule}</p><p>${limit}</p><div class="row">${btn('Ver origem dos números','nav:analises','primary')}${btn('Fechar','close-drawer')}</div></div>`}
function biAmount(label,value,sub,id,featured=false){return `<section class="card bi-kpi ${featured?'featured':''}"><div class="row space"><span class="label">${label}</span><button class="bi-help" type="button" data-act="bi-explain:${id}" aria-label="Entender ${esc(label)}">ⓘ</button></div><div class="value">${brl(value)}</div><small>${sub}</small></section>`}

function clinicCash(){return state.accounts.filter(a=>a.kind!=='personal').reduce((sum,a)=>sum+a.opening+state.tx.filter(t=>t.status==='liquidado'&&t.account===a.id).reduce((x,t)=>x+(t.kind==='entrada'?t.net:t.kind==='saida'?-t.net:0),0)+state.transfers.reduce((x,t)=>x+(t.to===a.id?t.value:0)-(t.from===a.id?t.value:0),0),0)}
function financialTotals(){let x=state.tx.filter(t=>t.status==='liquidado'&&state.accounts.find(a=>a.id===t.account)?.kind!=='personal');let income=x.filter(t=>t.kind==='entrada').reduce((s,t)=>s+t.net,0),expense=x.filter(t=>t.kind==='saida').reduce((s,t)=>s+t.net,0);let pendingIncome=state.tx.filter(t=>t.status==='previsto'&&t.kind==='entrada').reduce((s,t)=>s+t.net,0);let pendingOut=state.tx.filter(t=>t.status==='previsto'&&t.kind==='saida').reduce((s,t)=>s+t.net,0)+state.obligations.filter(o=>o.status==='previsto').reduce((s,o)=>s+o.value,0);return {income,expense,cash:clinicCash(),pendingIncome,pendingOut,net:income-expense}}
function reportRows(){return state.tx.filter(t=>state.filter==='all'||t.kind===state.filter||t.status===state.filter).map(t=>({data:t.date,tipo:t.kind,descricao:t.desc,bruto:brl(t.gross),taxas:brl(t.fees||0),liquido:brl(t.net),situacao:t.status,conta:state.accounts.find(a=>a.id===t.account)?.name||'Manual',paciente:person(t.patient),profissional:prof(t.professional),servico:state.services.find(a=>a.id===t.service)?.name||'',categoria:t.category||'',meio:t.method||'',vencimento:t.due||'',data_liquidacao:t.paid||'',fonte:t.source||''}))}
function financeView(){if(!safeFinanceAccess()&&!['lancamentos','novo'].includes(state.page))return renderReception();switch(state.page){case'resumo':return renderFinanceOverview();case'lancamentos':return renderTransactions();case'novo':return renderNewFinance();case'compromissos':return renderObligations();case'stone':return renderStone();case'repasses':return renderRepasses();case'convenios':return renderPlans();case'analises':return renderFinanceAnalytics();case'relatorios':return renderReports();case'config':return renderSettings();default:return renderFinanceOverview()}}
function renderFinanceOverview(){
 const b=financeBI(),hints=orientadorBI(b),waiting=state.tx.filter(t=>t.status==='aguardando validacao').length;
 return head('FINANCEIRO BI · VISÃO GERENCIAL','Resumo Financeiro','O que os dados de demonstração mostram e o que merece atenção.',btn('＋ Novo lançamento','nav:novo','primary')+btn('Analisar dados','nav:analises'))+
 `<div class="row space bi-toolbar"><span class="env-inline">DEMONSTRAÇÃO · DADOS SINTÉTICOS</span><label>Período <select id="bi-month">${options([['all','Todos os registros'],...monthlyTrend().map(x=>[x.month,x.month])],state.biMonth)}</select></label></div>`+
 `<div class="bi-kpis">${biAmount('Saldo demonstrativo',b.cash,'Contas próprias; não é extrato conciliado','caixa',true)}${biAmount('Fluxo líquido previsto',b.liquidity,'A receber − a pagar; horizonte dos registros','fluxo')}${biAmount('Resultado gerencial estimado',b.estimatedResult,'Não representa DRE contábil formal','resultado')}</div>`+
 `<div id="bi-drawer" class="bi-drawer" hidden></div>`+
 `<div class="bi-main-grid"><section class="card bi-primary-chart"><div class="row space"><div><h2>Evolução dos registros</h2><p class="tiny">Clique no mês para investigar os lançamentos daquele período.</p></div>${btn('Ver todos os meses','bi-clear','small')}</div>${biMonthlyChart()}<div class="row" style="margin-top:13px">${btn('Abrir análises do período','nav:analises','primary')}</div></section><section class="card bi-insights"><div class="row space"><h2>Orientador BI</h2><span class="badge">Até 3 insights</span></div>${hints.map(x=>`<div class="bi-insight"><b>✦ ${esc(x.label)}</b><p>${esc(x.msg)}</p>${btn('Investigar','nav:'+x.target,'small')}</div>`).join('')}</section></div>`+
 `<section class="card" style="margin-top:15px"><div class="row space"><div><h2>Pendências e próximas ações</h2><p class="tiny">Tarefas autorizadas; não são ordens de pagamento.</p></div>${btn('Histórico e relatórios','nav:relatorios','small')}</div><div class="attention-grid"><button data-act="nav:lancamentos"><b>${waiting}</b><span>Aguardando validação</span></button><button data-act="nav:compromissos"><b>${state.obligations.filter(x=>x.status==='previsto').length}</b><span>Parcelas em aberto</span></button><button data-act="nav:stone"><b>${state.stone.filter(x=>x.status!=='conciliado').length}</b><span>Stone a conferir</span></button></div></section>`+
 `<p class="bi-disclaimer">Os cálculos deste protótipo usam apenas registros sintéticos disponíveis. Competências, saldos bancários, taxas contratuais e completude da planilha devem ser validados antes de qualquer uso oficial.</p>`;
}
function renderFinanceAnalytics(){
 const x=financeBI(),trend=monthlyTrend();const scoped=periodTransactions().slice().sort((a,b)=>b.date.localeCompare(a.date));
 const revByService={};for(const t of x.incoming){const key=state.services.find(s=>s.id===t.service)?.name||'Sem serviço definido';revByService[key]=(revByService[key]||0)+biMoney(t)}
 const costByCategory={};for(const t of x.outgoing){const key=t.category||'Não classificada';costByCategory[key]=(costByCategory[key]||0)+biMoney(t)}
 const serviceRows=Object.entries(revByService).map(([k,v])=>`<tr><td>${esc(k)}</td><td class="right">${brl(v)}</td></tr>`),categoryRows=Object.entries(costByCategory).map(([k,v])=>`<tr><td>${esc(k)}</td><td class="right">${brl(v)}</td></tr>`);
 const records=scoped.map(t=>`<tr><td>${dateBR(t.date)}</td><td><b>${esc(t.desc)}</b><br><span class="tiny">${esc(t.id)}</span></td><td>${esc(t.kind)}</td><td>${brl(t.net)}</td><td>${badge(t.status)}</td><td>${btn('Ver','detail:'+t.id,'small')}</td></tr>`);
 return head('FINANCEIRO BI · INVESTIGAÇÃO','Análises e memória de cálculo','Investigue os registros que sustentam cada indicador, sem valores inventados.',btn('Voltar ao Resumo','nav:resumo')+btn('Excel','export:xlsx'))+
 `<div class="row space bi-toolbar"><span class="env-inline">DEMONSTRAÇÃO · ANÁLISES LOCAIS</span><label>Período <select id="bi-month">${options([['all','Todos os registros'],...trend.map(t=>[t.month,t.month])],state.biMonth)}</select></label></div>`+
 `<div class="bi-kpis">${biAmount('Entradas registradas',x.revenues,'Previstas e confirmadas','resultado')}${biAmount('Saídas registradas',x.costs,'Conforme classificações existentes','resultado')}${biAmount('Resultado estimado',x.estimatedResult,'Depende da completude dos dados','resultado')}</div><div id="bi-drawer" class="bi-drawer" hidden></div>`+
 `<div class="grid" style="margin-top:16px"><div class="c6">${box('Receita por serviço',table(['Serviço','Valor'],serviceRows),'Sem inventar margem por serviço')}</div><div class="c6">${box('Despesas por categoria',table(['Categoria','Valor'],categoryRows),'A ausência de classificação reduz a precisão')}</div></div>`+
 box('Registros que formam os resultados',table(['Data','Referência','Tipo','Valor','Estado','Ações'],records))+
 `<div class="card"><h2>Como interpretar estes resultados</h2><p>Caixa realizado, valores esperados e resultado por competência são medidas distintas. O valor gerencial apresentado é uma estimativa de demonstração que ainda não incorpora todas as obrigações e classificações necessárias para uma DRE formal.</p><div class="row">${btn('Entender caixa','bi-explain:caixa')}${btn('Entender previsão','bi-explain:fluxo')}${btn('Entender resultado','bi-explain:resultado')}</div></div>`;
}

function renderReception(){return renderTransactions()}
function renderTransactions(){
 const reception=!safeFinanceAccess();const rows=state.tx.filter(t=>!reception||t.owner===state.role).slice().reverse().map(t=>`<tr><td>${permissions()?`<input type="checkbox" aria-label="Selecionar ${esc(t.id)}" data-txselect="${esc(t.id)}" ${state.selectedTx.includes(t.id)?'checked':''}>`:''}<b>${esc(t.desc)}</b><div class="tiny">${esc(t.id)} · ${dateBR(t.date)}</div></td><td>${esc(t.kind)}</td><td>${brl(t.net)}</td><td>${badge(t.status)}</td><td>${esc(state.accounts.find(a=>a.id===t.account)?.name||'A classificar')}</td><td><div class="cell-actions">${t.status==='aguardando validacao'&&permissions()?btn('Aprovar','approve:'+t.id,'small'):''}${t.kind==='transferencia'&&t.status==='aprovado'&&permissions()?btn('Executar transferência','execute-transfer:'+t.id,'small'):''}${t.status==='previsto'&&!t.planPending&&permissions()?btn('Liquidar','settle:'+t.id,'small'):''}${btn('Detalhar','detail:'+t.id,'small')}</div></td></tr>`);
 return head('FINANCEIRO BI','Lançamentos e solicitações',reception?'Rascunhos e solicitações deste perfil demonstrativo. Sem acesso a saldos nem relatórios gerais.':'Registros, aprovações e liquidação são etapas distintas.',btn('＋ Novo lançamento','nav:novo','primary'))+
 (reception?`<div class="quick-tiles">${[['Novo lançamento','nav:novo','＋'],['Ler comprovante','modal:ocr','▧'],['Meus rascunhos','nav:lancamentos','▤'],['Enviados','nav:lancamentos','◷']].map(([t,a,i])=>`<button class="quick-tile" data-act="${a}"><strong>${i}</strong>${t}</button>`).join('')}</div>`:'')+
 (!reception?`<section class="card bulkbar"><div><b>Ações em lote</b><p class="tiny">Selecione lançamentos; cada item será validado separadamente.</p></div><div class="row">${btn('Aprovar selecionados','bulk-review:approve','small')}${btn('Liquidar selecionados','bulk-review:settle','small')}${btn('Limpar seleção','bulk-clear','small')}</div></section>`:'')+
 box('Histórico operacional',table(['Lançamento','Tipo','Valor','Situação','Origem','Ações'],rows));
}
function renderNewFinance(){
 const d=state.draft||{kind:'saida',statusType:'apagar',value:'',account:'cx-pj',method:'pix',date:DEMO_DATE,due:DEMO_DATE,desc:'',patient:'',professional:'',service:'',other:'',notes:'',installments:'1',first:DEMO_DATE,interest:'0',category:'',card:''};
 const type=d.kind||'saida',methods=type==='entrada'?[['pix','Pix'],['dinheiro','Dinheiro'],['boleto','Boleto'],['debito','Débito'],['credito','Crédito do paciente'],['outro','Outro']]:[['pix','Pix'],['dinheiro','Dinheiro'],['boleto','Boleto'],['debito','Débito'],['cartao-clinica','Cartão de crédito da clínica'],['beneficio','VA / VR permitido'],['outro','Outro']];
 const accountOptions=[...appOptions,['manual','Outro — informar referência']],isTransfer=type==='transferencia',isCard=['cartao-clinica','credito','beneficio'].includes(d.method),isInstall=isCard&&d.method!=='beneficio'||Number(d.installments)>1;
 const kindChooser=`<div class="operation-switch" role="group" aria-label="Tipo de lançamento">${[['entrada','↓ Entrada'],['saida','↑ Saída'],['transferencia','↔ Transferência']].map(([id,n])=>`<button type="button" class="${type===id?'on':''}" data-act="set-operation:${id}">${n}</button>`).join('')}</div>`;
 const overview=`<div class="fields"><div class="field"><label>Valor em R$ *</label><input required name="value" inputmode="decimal" placeholder="Ex.: 180,00" value="${esc(d.value)}"></div>${field('Data da operação','date','date',d.date,'required')}<div class="field full"><label>Descrição / finalidade *</label><input name="desc" required maxlength="150" value="${esc(d.desc)}" placeholder="${type==='entrada'?'Ex.: Consulta particular':type==='saida'?'Ex.: Compra de material':'Ex.: Transferência entre contas'}"></div></div>`;
 const status=isTransfer?'':`<div class="field"><label>Situação informada</label><select name="statusType">${options(type==='entrada'?[['recebido','Já recebi (a conferir)'],['previsto','A receber']]:[['pago','Já paguei (a conferir)'],['apagar','A pagar']],d.statusType)}</select></div>`;
 const pay=isTransfer?`<div class="fields">${select('Conta de origem','account',accountOptions,d.account)}${select('Conta de destino','to',appOptions,d.to||'cx-pj2')}</div>`:`<div class="fields">${status}${select('Meio de pagamento','method',methods,methods.some(m=>m[0]===d.method)?d.method:methods[0][0])}${select(type==='entrada'?'Conta que receberá':'Conta / origem do recurso','account',accountOptions,d.account)}</div>`;
 const specific=isCard&&!isTransfer?`<section class="context-fields"><h3>${d.method==='cartao-clinica'?'Compra com cartão da clínica':d.method==='beneficio'?'Cartão de benefício':'Venda no cartão do paciente'}</h3><div class="fields">${select('Cartão cadastrado (se aplicável)','card',[['','Selecionar / não informado'],...state.cards.filter(c=>d.method==='beneficio'?c.kind==='benefit':c.kind==='credit').map(c=>[c.id,c.name])],d.card)}${d.method==='beneficio'?'':field('Parcelas','installments','number',d.installments,'min="1" max="120"')}${d.method==='credito'?field('Referência de venda / Stone','stoneRef','text',d.stoneRef||''):''}</div></section>`:'';
 const more=`<details id="advanced-finance" class="advanced-panel" ${state.advanced?'open':''}><summary>▤ Mais detalhes · paciente, serviço, parcelas e condições</summary><div class="fields">${select('Paciente / referência','patient',patientOptions,d.patient)}${select('Serviço realizado','service',serviceOptions,d.service)}${select('Profissional','professional',profOptions,d.professional)}${select('Categoria','category',[['','Não classificada'],['Custo fixo','Custo fixo'],['Insumos/Procedimentos','Insumos/Procedimentos'],['Aparelhos/Produtos','Aparelhos/Produtos'],['Pessoal/Comissões','Pessoal/Comissões'],['Taxas/Impostos','Taxas/Impostos'],['Outros/Excepcionais','Outros/Excepcionais']],d.category)}${field('Vencimento / previsão','due','date',d.due)}${!isCard?field('Parcelas (despesas)','installments','number',d.installments,'min="1" max="120"'):''}${field('Primeiro vencimento','first','date',d.first)}${field('Juros totais em R$','interest','text',d.interest)}${field('Origem manual ou detalhe do terceiro','other','text',d.other)}${field('Referência de comprovante','source','text',d.source||'')}${textArea('Observações','notes',d.notes)}</div></details>`;
 const review=state.review?`<section class="card review-card"><div class="row space"><h2>Conferência antes de registrar</h2>${btn('Corrigir dados','finance-edit','small')}</div><div class="review-grid">${[['Operação',type],['Descrição',d.desc],['Valor',brl(moneyInput(d.value))],['Situação',isTransfer?'Transferência':d.statusType],['Meio',isTransfer?'Entre contas':d.method],['Conta',state.accounts.find(a=>a.id===d.account)?.name||'Outra origem'],['Parcelas',d.installments||'1']].map(([name,value])=>`<div><span>${esc(name)}</span><b>${esc(value)}</b></div>`).join('')}</div><p class="tiny">Na Recepção, esta confirmação envia apenas uma solicitação para a Dra. Simone. Valores não são liquidados automaticamente.</p></section>`:'';
 return head('FINANCEIRO BI · REGISTRO','Novo lançamento','Comece pelo essencial; informe detalhes apenas quando forem necessários.',btn('Configurar conta / cartão','modal:account'))+`<form id="finance-entry">${kindChooser}<section class="card fast-form">${overview}<div class="compact-divider"></div>${pay}${specific}${more}${review}<div class="formfoot sticky-action"><button type="submit" class="btn primary">${state.review?(state.role==='recepcao'?'Enviar para Dra. Simone':'Confirmar no demonstrativo'):'Conferir lançamento →'}</button>${btn('Cancelar','finance-reset')}</div></section></form>`;
}
function renderObligations(){const rows=state.obligations.slice().reverse().map(o=>`<tr><td>${esc(o.name)}<div class="tiny">${esc(o.id)}</div></td><td>${dateBR(o.due)}</td><td>${brl(o.value)}</td><td>${badge(o.status)}</td><td>${esc(o.account)}</td><td>${o.status==='previsto'&&permissions()?btn('Pagar parcela','pay-ob:'+o.id,'small'):''}</td></tr>`);return head('FINANCEIRO / COMPROMISSOS','Parcelas e recorrências','Distingue obrigação, competência, vencimento e baixa, com controle de centavos.',btn('＋ Nova obrigação','modal:obligation','primary')+btn('＋ Custo recorrente','modal:recurring'))+`<div class="grid">${stat('Total a pagar',state.obligations.filter(o=>o.status==='previsto').reduce((a,o)=>a+o.value,0),'Obrigações não liquidadas','c4')}${stat('Parcelas pagas',state.obligations.filter(o=>o.status==='liquidado').reduce((a,o)=>a+o.value,0),'Eventos confirmados no simulador','c4')}${stat('Recorrências modelo',state.recurring.reduce((a,o)=>a+o.value,0),'Valores padrão, não caixa','c4')}</div>`+box('Obrigações previstas e pagas',table(['Referência','Vencimento','Valor','Estado','Conta','Ação'],rows))+box('Custos fixos e recorrentes',state.recurring.map(r=>`<div class="task"><div class="detail"><b>${esc(r.name)} · ${brl(r.value)}</b><p>Todo dia ${r.day}; gera ocorrência prevista, nunca pagamento automático.</p></div>${btn('Gerar competência','generate:'+r.id,'small')}</div>`).join('')||'<div class="empty">Use “Custo recorrente” para adicionar uma regra de demonstração.</div>')}
function renderStone(){const rows=state.stone.map(s=>`<tr><td>${esc(s.id)}<div class="tiny">${dateBR(s.date)} · ${esc(s.method)}</div></td><td>${brl(s.gross)}</td><td>${s.fee===null?badge('Taxa ausente'):brl(s.fee)}</td><td>${s.fee===null?'—':brl(s.expected)}</td><td>${s.credit===null?'—':brl(s.credit)}</td><td>${badge(s.status)}</td><td>${s.status!=='conciliado'&&s.fee!==null?btn('Conciliar','reconcile:'+s.id,'small'):''}</td></tr>`);return head('FINANCEIRO / STONE','Cartões e conciliação','Bruto, MDR, antecipação, líquido previsto, crédito e divergência permanecem separados.',btn('＋ Venda cartão demo','modal:stone','primary'))+note('Sem tabela contratual verdadeira: o cálculo automático oficial fica bloqueado. Um usuário autorizado pode informar taxa manual fictícia com fonte. Nenhuma comunicação com a Stone.')+box('Vendas e recebíveis demonstrativos',table(['Operação','Bruto','Taxa MDR','Líquido previsto','Creditado','Estado','Ação'],rows))+box('Regras de cálculo e prevenção',`<div class="task"><div class="detail"><b>Não sobrepor taxa original durante divergência</b><p>Valor esperado e valor depositado podem divergir; a diferença fica aberta para apuração.</p></div>${badge('Proteção')}</div><div class="task"><div class="detail"><b>Tarifas versionadas por clínica e vigência</b><p>O protótipo não carrega tabela Stone oficial. Taxa manual exige fonte e responsável.</p></div>${badge('Pendente contrato')}</div>`)}
function renderRepasses(){const settled=state.tx.filter(t=>t.kind==='entrada'&&t.status==='liquidado'&&t.professional);const rows=state.people.map(p=>{const base=settled.filter(x=>x.professional===p.id).reduce((a,t)=>a+t.net,0);const amount=p.rate===null?null:Math.round(base*p.rate/100);return `<tr><td><b>${esc(p.name)}</b><div class="tiny">${esc(p.notes)}</div></td><td>${brl(base)}</td><td>${p.rate??'—'}${p.rate===null?'':'%'}</td><td>${amount===null?'A definir':brl(amount)}</td><td>${badge('estimativa sem validação')}</td><td>${btn('Editar regra','modal:rate:'+p.id,'small')}</td></tr>`});return head('FINANCEIRO / REPASSES','Repasses profissionais','Percentuais são referências informadas, mas bases de cálculo e contratos ainda dependem de conferência.',btn('Ver histórico','nav:relatorios'))+note('Corte dia 10 e previsão de pagamento dia 15 são parâmetros a confirmar. Nenhum valor desta tela constitui autorização de pagamento.')+box('Apuração ilustrativa por profissional',table(['Profissional','Base recebida','Percentual','Prévia','Estado','Configurar'],rows))+box('Critérios de cálculo',`<div class="task"><div class="detail"><b>Regras com vigência, serviço e contrato</b><p>Evita aplicar novas regras retroativamente; taxas, devoluções, descontos e glosas exigem cláusulas confirmadas.</p></div></div><div class="task"><div class="detail"><b>Patrimônio e equipamentos não são comissão</b><p>Aparelhos, compras, serviços terceirizados e manutenções possuem cadastro de patrimônio/estoque ou despesas, não regra automática de repasse.</p></div></div>`)}
function renderPlans(){const rows=state.plans.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.service)}</td><td>${brl(x.price)}</td><td>${brl(x.patient)}</td><td>${brl(x.price-x.patient)}</td><td>${esc(x.start)}</td></tr>`);return head('FINANCEIRO / CONVÊNIOS','Convênios e parcerias','Clínica predominantemente particular: cadastros e calculadora demonstrativa para condições comerciais específicas.',btn('＋ Contrato fictício','modal:plan','primary'))+note('Particular, plano credenciado e particular com reembolso são situações diferentes. Reembolso particular não cria recebível contra operadora.')+box('Contratos/tabelas de exemplo',table(['Operadora/parceria','Serviço','Valor total','Parte paciente','Parte operadora','Vigência'],rows))+box('Calculadora contratual',`<form id="plan-calc"><div class="fields">${field('Valor contratual R$','total','text','180,00','required')}${field('Coparticipação incluída no total R$','patient','text','30,00','required')}${field('Recebido da operadora R$ (demonstrativo)','received','text','140,00')}${select('Natureza do atendimento','type',[['convenio','Convênio credenciado'],['particular','Particular'],['reembolso','Particular com reembolso']], 'convenio')}</div><div class="formfoot"><button class="btn primary" type="submit">Calcular divisão e diferença</button></div></form><div id="calc-result" class="notice">Use a calculadora para verificar a previsão, valores recebidos e diferenças; sem criar lançamento.</div>`)+box('Tratamento administrativo de pacientes',`<p>Condições comerciais e alertas devem ser objetivos: cortesia autorizada, atendimento prioritário legítimo, solicitação de retorno ou reclamação em andamento. Nunca atribuir automaticamente rótulos depreciativos.</p>`)}
function renderReports(){let tx=state.tx.filter(t=>state.filter==='all'||t.kind===state.filter||t.status===state.filter);const rows=tx.slice().reverse().map(t=>`<tr><td>${dateBR(t.date)}</td><td>${esc(t.desc)}</td><td>${esc(t.kind)}</td><td>${brl(t.gross)}</td><td>${brl(t.fees)}</td><td>${brl(t.net)}</td><td>${badge(t.status)}</td></tr>`);return head('FINANCEIRO / HISTÓRICO','Histórico e relatórios','Filtros, rastreabilidade e exportações em Excel verdadeiro e PDF demonstrativo personalizado.',btn('Baixar Excel (.xlsx)','export:xlsx','primary')+btn('Baixar PDF','export:pdf'))+`<div class="row" style="margin-bottom:12px"><label for="report-filter">Exibir: </label><select id="report-filter">${options([['all','Todos'],['entrada','Entradas'],['saida','Saídas'],['previsto','Previstos'],['liquidado','Liquidados'],['aguardando validacao','Aguardando validação']],state.filter)}</select></div>`+box('Operações',table(['Data','Descrição','Tipo','Bruto','Taxa','Líquido','Estado'],rows))+box('Rastreabilidade da demonstração',state.audit.slice(0,12).map(x=>`<div class="task"><div class="detail"><b>${esc(x.message)}</b><p>${esc(x.who)} · ${esc(x.at)} · evento em memória, não auditoria de produção</p></div></div>`).join('')||'<div class="empty">Nenhuma operação realizada nesta sessão.</div>')}
function renderSettings(){return head('FINANCEIRO / CONFIGURAÇÕES','Contas e parâmetros','Cadastros com titular, tipo, origem e vinculação; somente dados demonstrativos.',btn('＋ Conta ou cartão','modal:account','primary'))+`<div class="grid"><div class="c6">${box('Contas e carteiras',state.accounts.map(a=>`<div class="task"><div class="detail"><b>${esc(a.name)}</b><p>${esc(a.owner)} · ${esc(a.kind)} · saldo demonstrativo inicial ${brl(a.opening)}</p></div></div>`).join(''))}</div><div class="c6">${box('Cartões e benefícios',state.cards.map(a=>`<div class="task"><div class="detail"><b>${esc(a.name)}</b><p>${esc(a.kind)} · ${esc(a.owner)}</p></div></div>`).join(''))}</div></div>`+box('Princípios de configuração',`<p>Conta pessoal não entra no caixa próprio; benefício não é dinheiro livre; compras no crédito geram obrigação de fatura. Serviços, categorias, regras e contas são versionados na implementação real. Não existem chaves Supabase, cobrança, Stone ou salários conectados neste pacote.</p>`)}
function patientView(){switch(state.page){case 'fila':return viewIntakes();case 'prontuario':return viewRecords();default:return viewPatientDirectory()}}
function viewPatientDirectory(){return head('M2 / ATENDIMENTO E PACIENTES','Cadastro único de pacientes','Identidade, contatos, responsável legal e cobrança. CPF é atributo condicional, não ID técnico.',btn('＋ Paciente fictício','modal:patient','primary'))+note('Todos os pacientes são exemplos inventados. O sistema não recebe prontuários reais. Dados clínicos são separados dos administrativos.')+box('Pacientes da demonstração',state.patients.map(p=>`<div class="task"><div class="detail"><b>${esc(p.id)} · ${esc(p.name)}</b><p>${esc(p.phone)} · ${esc(p.email)}</p><p>${p.tag?`Condição administrativa: ${esc(p.tag)} · ${esc(p.note)}`:'Sem alerta administrativo'} ${p.legal?' · Responsável: '+esc(p.legal):''}</p></div><div class="cell-actions">${btn('Ver história','record:'+p.id,'small')}${btn('Abrir atendimento','new-intake:'+p.id,'small')}</div></div>`).join(''))+box('Segurança e deduplicação',`<p>Busca por nome/CPF quando legítimo e disponível, com revisão de possíveis duplicidades. Não unir cadastros automaticamente nem inferir dados de saúde. A recepção usa cadastro administrativo mínimo e não visualiza evolução clínica.</p>`)}
function viewIntakes(){return head('M2 / FLUXO ASSISTENCIAL','Fila central e atendimento','Agendamento, chegada, fila, ato clínico e cobrança são acontecimentos separados.',btn('＋ Atendimento avulso / encaixe','modal:intake','primary'))+box('Fila operacional',state.intakes.map(i=>`<div class="task"><div class="detail"><b>${esc(person(i.patient))} · ${esc(i.type)}</b><p>${esc(i.id)} · ${dateBR(i.date)} · Profissional: ${esc(prof(i.professional))} · ${esc(i.notes||'')}</p></div><div class="cell-actions">${badge(i.status)}${btn('Próxima etapa','intake-next:'+i.id,'small')}</div></div>`).join('')||'<div class="empty">Nenhuma pessoa aguardando nesta sessão. Um check-in pode criar evento de fila sintético.</div>')+note('A recepção ou a profissional podem organizar a fila. Atos clínicos e assinaturas exigem profissional habilitado; esta simulação não produz prontuário clínico válido.')}
function viewRecords(){return head('M2 / PRONTUÁRIO','Prontuário longitudinal','Linha do tempo clínica demonstrativa; documento externo preservado e resumo validado são registros distintos.')+box('Pacientes e linha do tempo de exemplos',state.patients.map(p=>`<div class="task"><div class="detail"><b>${esc(p.name)}</b><p>ID interno: ${esc(p.id)} · prontuário longitudinal fictício vinculado, sem novos prontuários por retorno.</p><p>Exames → avaliação → evolução → documentos externos e termos AASI, conforme permissão clínica.</p></div>${btn('Ver eventos','record:'+p.id,'small')}</div>`).join(''))+note('Esta tela é demonstrativa. Não implementa prontuário eletrônico, assinaturas da Fonoaudiologia, guarda legal nem controle assistencial em banco.')}
function agendaView(){if(state.page==='comunicacoes')return head('M3 / AGENDA','Comunicação assistida','E-mail simulado, WhatsApp manual e registros retrospectivos. Nada é enviado.',btn('＋ Registrar contato','modal:message','primary'))+box('Interações e mensagens',state.messages.map(m=>`<div class="task"><div class="detail"><b>${esc(m.method)} · ${esc(person(m.patient))}</b><p>${esc(m.text)} · ${esc(m.date)} · Registro manual, não comprova mensagem enviada pelo SGI.</p></div></div>`).join('')||'<div class="empty">Registre um contato fictício para observar o histórico de comunicações.</div>')+note('Confirmação de presença não cancela agendamento por falta de resposta. Remarcação/cancelamento exige aprovação inicial de pessoa autorizada.');return head('M3 / AGENDA','Agenda e encaixes','Calendário operacional e solução de imprevistos; sem envios reais ou reservas em banco.',btn('＋ Agendamento','modal:appointment','primary')+btn('Registrar WhatsApp','nav:comunicacoes'))+box('Agenda e compromissos demonstrativos',state.appointments.map(a=>`<div class="task"><div class="detail"><b>${dateBR(a.date)} às ${esc(a.time)} · ${esc(person(a.patient))}</b><p>${esc(prof(a.professional))} · ${esc(a.source)} · ${esc(a.notes)}</p></div><div class="cell-actions">${badge(a.status)}${btn('Chegada','checkin:'+a.id,'small')}${btn('Solicitar encaixe','request-encaixe:'+a.id,'small')}</div></div>`).join(''))+note('Encaixe deve ser autorizado inicialmente pela profissional. Atraso/falta não dispara cancelamento ou cobrança por relógio.')}
function documentsView(){return docNewView()}
function legacyDocumentsView(){if(state.page==='termos')return head('M4 / DOCUMENTOS','Termos AASI','Teste, entrega, devolução, troca e garantia, sempre vinculados à identidade da unidade e ao paciente.',btn('＋ Termo sintético','modal:document','primary'))+box('Emissões de exemplo',docList())+note('Gerar um termo não movimenta estoque nem liquida venda. Nenhum documento desta demonstração possui assinatura válida.');return head('M4 / DOCUMENTOS','Biblioteca e modelos','Arquivos privados e controle de versões na arquitetura futura; a prévia pública usa somente dados sintéticos.',btn('＋ Criar termo fictício','modal:document','primary'))+box('Modelos preparados',`<div class="grid">${['Termo de teste/empréstimo AASI','Termo de entrega','Termo de devolução','Orientações de adaptação','Termo de garantia','Modelo institucional'].map(t=>`<div class="card c6"><h3>${t}</h3><p>Preenchimento guiado · revisão · versão</p>${btn('Prévia exemplo','preview-template:'+t,'small')}</div>`).join('')}</div>`)+box('Arquivos sintéticos',docList())}
function docList(){return state.documents.map(d=>`<div class="task"><div class="detail"><b>${esc(d.type)}</b><p>${esc(d.version)} · ${esc(d.serial)} · ${esc(person(d.patient))}</p></div><div class="cell-actions">${badge(d.status)}${btn('Prévia','preview-doc:'+d.id,'small')}</div></div>`).join('')}
