function openModal(kind,arg=''){const [title,body]=modalHTML(kind,arg);let el=document.createElement('div');el.id='active-modal';el.className='modal-overlay';el.setAttribute('role','presentation');el.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modaltitle"><div class="row space"><h2 id="modaltitle">${esc(title)}</h2><button class="btn small" type="button" data-act="modal-close" aria-label="Fechar diálogo">✕</button></div>${body}</div>`;document.body.appendChild(el);el.querySelector('input:not([type=hidden]),select,button')?.focus()}
function closeModal(){document.querySelector('#active-modal')?.remove()}
function getForm(form){const o=Object.fromEntries(new FormData(form).entries());for(const k of Object.keys(o))if(typeof o[k]==='string')o[k]=o[k].trim();return o}
function nextMonths(date,i,day){let [y,m]=date.split('-').map(Number);let dt=new Date(y,m-1+i,1);let final=new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate();return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(Math.min(Number(day)||dt.getDate(),final)).padStart(2,'0')}`}
function makeObligations(name,total,interest,count,first,account,origin='manual'){if(count<1||count>120||!Number.isInteger(count))throw Error('Parcelas devem ser entre 1 e 120');if(total<=0)throw Error('Valor contratado inválido');const all=total+interest;const per=Math.floor(all/count);const day=Number(first.slice(-2));let batch=uid('PAR');for(let i=0;i<count;i++)state.obligations.push({id:batch+'-'+(i+1),name:`${name} (${i+1}/${count})`,value:per+(i===count-1?all-per*count:0),due:nextMonths(first,i,day),account,status:'previsto',paid:'',origin});return batch}


function applyApproval(t){
 if(t.status!=='aguardando validacao')return;
 t.status=t.kind==='transferencia'?'aprovado':'previsto';
 if(t.planPending&&t.kind==='saida'){
  if(!state.obligations.some(o=>o.origin===t.id))makeObligations(t.desc,t.net,t.interest||0,t.installments||1,t.first||t.due,t.account,t.id);
  audit('Obrigação parcelada registrada somente após aprovação '+t.id);
 }
}
function renderLab(){
 if(state.role!=='dev')return head('AMBIENTE DE DEMONSTRAÇÃO','Área não disponível','Selecione Dev/QA somente no protótipo público; não é acesso técnico real.');
 const body=state.audit.slice(0,18).map(a=>`<div class="task"><div class="detail"><b>${esc(a.message)}</b><p>${esc(a.id)} · ${esc(a.at)} · ${esc(a.who)}</p></div></div>`).join('')||'<div class="empty">Sem eventos de demonstração nesta sessão.</div>';
 return head('LABORATÓRIO DEV / QA','Cenários de teste','Ferramentas de apresentação com dados sintéticos. Sem Supabase, RLS, sessão autenticada ou logs reais.',btn('Reiniciar dados demonstrativos','lab-reset','primary'))+`<div class="grid"><div class="c6">${box('Como simular perfis',`<p>Escolha o perfil na barra superior, verifique quais menus e ações aparecem e volte ao Dev/QA para inspecionar os eventos fictícios. A autorização real dependerá de Supabase e backend protegidos.</p><p>Este ambiente não cria conta, não coleta dados reais e não substitui testes de segurança.</p>`)}</div><div class="c6">${box('Estado técnico da demonstração',`<div class="task"><div class="detail"><b>Backend e autenticação</b><p>Não conectados · nenhum teste RLS executado</p></div>${badge('DEMO')}</div><div class="task"><div class="detail"><b>Lançamentos locais</b><p>${state.tx.length} registro(s) somente em memória</p></div></div>`)}</div></div>`+box('Eventos sintéticos',body);
}

function handleFinanceEntry(f,form){
 let d={...(state.draft||{}),...form};d.source=d.source||d.stoneRef||'';d.kind=(state.draft?.kind||form.kind||'saida');
 if(!d.statusType)d.statusType=d.kind==='entrada'?'recebido':'apagar';
 const value=moneyInput(d.value),interest=moneyInput(d.interest);if(!d.desc?.trim()||value<=0)throw Error('Informe descrição e valor maior que zero.');
 if(!d.date)throw Error('Informe a data da operação.');
 if(d.account==='manual'&&!d.other?.trim())throw Error('Descreva a origem manual ou o terceiro responsável.');
 if(d.kind==='transferencia'){
  if(!d.to||d.account===d.to)throw Error('Origem e destino devem ser contas distintas.');
  if([d.account,d.to].some(id=>state.accounts.find(a=>a.id===id)?.kind==='personal'))throw Error('Contas pessoais requerem operação de aporte ou reembolso, não transferência interna.');
 }
 if(d.kind==='saida'&&d.method==='credito')throw Error('Selecione cartão da clínica para saída; venda no crédito só é entrada.');
 if(d.kind==='entrada'&&['cartao-clinica','beneficio'].includes(d.method))throw Error('Cartão da clínica não é forma de recebimento do paciente.');
 if(['cartao-clinica','beneficio'].includes(d.method)){
  const c=state.cards.find(c=>c.id===d.card);if(!c)throw Error('Escolha um cartão cadastrado para esta operação.');
  if(d.method==='cartao-clinica'&&c.kind!=='credit'||d.method==='beneficio'&&c.kind!=='benefit')throw Error('Este cartão não corresponde à modalidade escolhida.');
 }
 const installments=Number(d.installments)||1;if(!Number.isInteger(installments)||installments<1||installments>120)throw Error('Parcelas devem estar entre 1 e 120.');
 if(state.review!==true){state.draft=d;state.review=true;render();return}
 if(d.kind==='transferencia'){
  if(state.role==='recepcao'){
   const t={id:uid('FIN'),kind:'transferencia',desc:d.desc,account:d.account,to:d.to,gross:value,fees:0,net:value,date:d.date,due:d.date,method:'interno',status:'aguardando validacao',owner:state.role,source:'Pedido de transferência',notes:d.notes||'',patient:'',service:'',professional:''};state.tx.push(t);audit('Solicitação de transferência submetida; não movimenta caixa');state.feedback={title:'Transferência enviada para validação',body:`${t.id} · Nenhum saldo foi alterado.`};
  }else{
   state.transfers.push({id:uid('TRF'),from:d.account,to:d.to,value,date:d.date});audit('Transferência interna demonstrativa, sem receita ou despesa');state.feedback={title:'Transferência demonstrativa registrada',body:'Movimentação entre contas próprias, sem alterar o total consolidado.'};
  }
 }else{
  const isCardExpense=d.kind==='saida'&&d.method==='cartao-clinica';const installmentExpense=d.kind==='saida'&&installments>1;const needsObligations=isCardExpense||installmentExpense;
  const txn={id:uid('FIN'),kind:d.kind,desc:d.desc,patient:d.patient||'',service:d.service||'',professional:d.professional||'',category:d.category||'',gross:value,fees:0,net:value,account:d.account,date:d.date,due:d.due||d.date,paid:'',method:d.method,status:state.role==='recepcao'?'aguardando validacao':'previsto',owner:state.role,source:d.source||d.other||'Lançamento demonstrativo',notes:d.notes||'',declaredStatus:d.statusType,card:d.card||'',installments,interest,first:d.first||d.due||d.date,planPending:needsObligations};
  state.tx.push(txn);
  if(needsObligations&&state.role!=='recepcao'){makeObligations(d.desc+(d.card?' · '+(state.cards.find(c=>c.id===d.card)?.name||'Cartão') :''),value,interest,installments,txn.first,txn.account,txn.id);audit('Parcelamento gerado após registro autorizado no demonstrativo');}
  else audit('Lançamento '+txn.id+' → '+txn.status+'; sem liquidação automática');
  state.feedback={title:state.role==='recepcao'?'Solicitação enviada para aprovação':'Lançamento criado no demonstrativo',body:`${txn.id} · ${brl(txn.net)} · ${txn.status}. A previsão não altera o caixa.`};
 }
 state.draft=null;state.review=false;state.advanced=false;go('finance','lancamentos');return;
}

function handleSubmit(ev){const f=ev.target;if(!f.id)return;ev.preventDefault();const d=getForm(f);if(f.id==='dev-login'){if(d.user.toUpperCase()==='DEV'&&d.password==='DEV2026'){sessionStorage.setItem('SGI_RC8_DEV_LOGIN','yes');state.role='dev';render();toast('Laboratório DEV liberado. Somente dados fictícios.');}else toast('Credenciais da demonstração incorretas.');return;}if(sessionStorage.getItem('SGI_RC8_DEV_LOGIN')!=='yes')return;try{switch(f.id){
case'finance-entry':{return handleFinanceEntry(f,d);}
case'entity-form':{if(!/exemplo|fict[ií]ci|demo/i.test(d.name))throw Error('Use apenas um nome fictício com Exemplo, Fictício ou Demo.');let existing=extra.records.find(x=>x.name.toLowerCase()===d.name.toLowerCase()&&x.kind===d.kind);if(existing)throw Error('Nome igual já cadastrado ('+existing.id+'). Confira antes de criar outro.');const id=uid(d.kind==='pf'?'PES':'ORG');extra.records.unshift({id,kind:d.kind,name:d.name,roles:[d.role],phone:d.phone||'',mail:d.mail||'',notes:d.notes||'',active:true,related:d.related||''});if(d.kind==='pf'&&d.role==='paciente'){state.patients.push({id,name:d.name,phone:d.phone,email:d.mail,legal:'',tag:'',note:''});patientOptions.push([id,d.name])}if(d.kind==='pf'&&d.role==='profissional'){state.people.push({id,name:d.name,rate:null,base:'pendente',notes:'Sem contrato de repasse validado'});profOptions.push([id,d.name])}audit('Identidade fictícia '+id+' criada com vínculo '+d.role);go('cadastro','lista');toast('Cadastro fictício criado: '+id);return;}
case'entity-link-form':{const p=extra.records.find(x=>x.id===d.id);if(!p)throw Error('Pessoa não encontrada');if(p.roles.includes(d.role))throw Error('Vínculo já existe; confira a ficha.');p.roles.push(d.role);if(d.role==='paciente'&&p.kind==='pf'&&!state.patients.some(x=>x.id===p.id)){state.patients.push({id:p.id,name:p.name,phone:p.phone,email:p.mail,legal:'',tag:'',note:''});patientOptions.push([p.id,p.name])}if(d.role==='profissional'&&p.kind==='pf'&&!state.people.some(x=>x.id===p.id)){state.people.push({id:p.id,name:p.name,rate:null,base:'pendente',notes:''});profOptions.push([p.id,p.name])}audit('Novo vínculo fictício criado para '+p.id);break;}
case'budget-form':{let q=Number(d.qty);if(!Number.isInteger(q)||q<1||q>100)throw Error('Quantidade inválida');let a=moneyInput(d.amount),a2=moneyInput(d.amount2),discount=moneyInput(d.discount);if(!d.person||!d.item||a<=0||discount<0)throw Error('Confira cliente, serviço, valor e desconto.');let items=[{label:d.item,qty:q,amount:a}];if(d.item2){if(a2<=0)throw Error('Informe o valor do segundo item');items.push({label:d.item2,qty:1,amount:a2})}let total=items.reduce((sum,i)=>sum+i.amount*i.qty,0)-discount;if(total<0)throw Error('Desconto maior que valor contratado.');let b=extra.budgets.find(x=>x.id===d.budgetid);if(b){if(b.status!=='rascunho')throw Error('Somente rascunhos são editáveis');Object.assign(b,{person:d.person,owner:d.owner,items,discount,total,terms:d.terms});audit('Rascunho orçamentário fictício revisado '+b.id)}else{b={id:uid('ORC'),person:d.person,owner:d.owner,items,discount,total,terms:d.terms,status:'rascunho',version:1,charge:null};extra.budgets.unshift(b);audit('Orçamento fictício criado '+b.id);}break;}
case'docnew-form':{let o={id:uid('DOC'),type:d.type,person:d.person,version:1,status:'rascunho',notes:d.notes||''};extra.files.unshift(o);audit('Rascunho documental '+o.id);break;}
case'govaccess-form':{if(!d.subject||!d.scope)throw Error('Informe pessoa e escopo');extra.govRequests.unshift({id:uid('GOV'),type:d.type,subject:d.subject,scope:d.scope,notes:d.notes,status:'aguardando aprovação',requested:DEMO_DATE});audit('Solicitação fictícia de Governança');break;}
case'risk-form':{extra.incidents.unshift({id:uid('RSK'),type:d.type,severity:d.severity,description:d.description||'Sem detalhes',status:'aberto'});audit('Evento fictício de risco');break;}
case'contingency-form':{if(extra.contingency.some(x=>x.code.toLowerCase()===d.code.toLowerCase()))throw Error('Código já usado — registro possivelmente duplicado.');extra.contingency.unshift({...d,status:'em conferência'});audit('Ficha manual fictícia recebida para conferência');break;}
case'support-form':{extra.support.unshift({id:uid('SUP'),subject:d.subject,module:d.module,priority:d.priority,notes:d.notes,status:'aberto'});audit('Protocolo de suporte em demonstração, sem envio AA.dev');break;}
case'social-form':{let reach=Number(d.reach),views=Number(d.views),engagement=Number(d.engagement);if([reach,views,engagement].some(x=>!Number.isInteger(x)||x<0))throw Error('Métricas inválidas');extra.social.push({...d,reach,views,engagement,id:uid('MET')});audit('Métrica social informada manualmente na demonstração');break;}
case'marketing-post-form':{extra.marketing.push({...d,id:uid('POST')});audit('Publicação fictícia planejada; sem postagem real');break;}
case'account-form':{if(!d.name||!d.owner)throw Error('Identifique descrição e titular.');if(['credit','benefit'].includes(d.kind))state.cards.push({id:uid('CRD'),name:d.name,kind:d.kind,owner:d.owner,limit:null});else state.accounts.push({id:uid('ACC'),name:d.name,kind:d.kind,owner:d.owner,opening:moneyInput(d.opening)});audit('Cadastro de origem financeira fictícia');break;}
case'ob-form':{makeObligations(d.name,moneyInput(d.total),moneyInput(d.interest),Number(d.count),d.first,d.account);audit('Parcelas geradas com valores exatos em centavos');break;}
case'recurring-form':{let day=Number(d.day);if(day<1||day>31||moneyInput(d.value)<=0)throw Error('Confira valor e dia do mês');state.recurring.push({id:uid('REC'),name:d.name,value:moneyInput(d.value),day,account:d.account});audit('Regra recorrente fictícia registrada');break;}
case'stone-form':{const gross=moneyInput(d.gross),r=d.rate===''?null:pct(d.rate),advance=moneyInput(d.advance);if(gross<=0||r!==null&&(r<0||r>100))throw Error('Valor ou percentual inválido');if(r!==null&&!d.source)throw Error('Taxa manual exige fonte/justificativa.');const fee=r===null?null:Math.round(gross*r/100),expected=fee===null?null:gross-fee-advance;if(expected!==null&&expected<0)throw Error('Taxas e antecipação ultrapassam o bruto.');state.stone.unshift({id:uid('STN'),date:DEMO_DATE,name:d.name,method:d.method,installments:Number(d.installments)||1,gross,fee,advance,expected,credit:null,status:fee===null?'taxa pendente':'recebível previsto',source:d.source||''});audit('Venda Stone simulada; sem crédito bancário');break;}
case'plan-form':{let price=moneyInput(d.price),patient=moneyInput(d.patient);if(price<=0||patient<0||patient>price)throw Error('Coparticipação precisa estar incluída no total.');state.plans.push({name:d.name,service:state.services.find(x=>x.id===d.service)?.name||'Outro',price,patient,start:d.start});audit('Parceria contratual fictícia');break;}
case'plan-calc':{let total=moneyInput(d.total),part=moneyInput(d.patient),received=moneyInput(d.received);if(total<=0||part>total||part<0)throw Error('Coparticipação inválida.');let expected=d.type==='convenio'?total-part:0,rec=d.type==='convenio'?received:0;let el=$('#calc-result');el.innerHTML=`<div><b>Total contratado:</b> ${brl(total)} · <b>Paciente:</b> ${brl(d.type==='convenio'?part:total)}</div><div><b>Operadora prevista:</b> ${brl(expected)} · <b>Recebido da operadora:</b> ${brl(rec)}</div><div><b>Diferença a conciliar:</b> ${brl(expected-rec)} — sem presumir glosa definitiva.</div>`;return;}
case'patient-form':{if(!d.name.toLowerCase().includes('exemplo')&&!d.name.toLowerCase().includes('fictício'))throw Error('Use apenas nomes claramente fictícios, com “Exemplo” ou “Fictício”.');state.patients.push({id:uid('PAC'),name:d.name,phone:d.phone,email:d.email,legal:d.legal,tag:d.tag,note:d.note});audit('Paciente sintético adicionado');break;}
case'intake-form':{if(!d.patient||!d.professional)throw Error('Selecione paciente e profissional');state.intakes.push({id:uid('ATD'),patient:d.patient,professional:d.professional,type:d.type,date:DEMO_DATE,notes:d.notes,status:'em espera'});audit('Atendimento fictício criado');break;}
case'appointment-form':{if(!d.patient||!d.professional||!d.date)throw Error('Preencha campos necessários.');state.appointments.push({id:uid('AG'),patient:d.patient,professional:d.professional,date:d.date,time:d.time,status:'agendado',source:'agendamento',notes:d.notes});audit('Agendamento sintético criado');break;}
case'message-form':{if(!d.patient)throw Error('Selecione um paciente fictício');state.messages.unshift({id:uid('MSG'),...d});audit('Interação retrospectiva manual fictícia');break;}
case'document-form':{if(!d.patient||!d.serial)throw Error('Selecione paciente e número de série');state.documents.unshift({id:uid('DOC'),type:d.type,patient:d.patient,serial:d.serial,status:'rascunho não assinado',version:'V1 · exemplo',notes:d.notes});audit('Termo fictício gerado sem assinatura');break;}
case'stock-form':{let i=state.inventory.find(x=>x.id===d.id);if(!i)throw Error('Unidade não encontrada');if(d.status==='disponivel'&&i.status==='conferencia'&&!d.notes)throw Error('Retorno ao disponível exige evidência de conferência.');if(d.status==='vendido'&&!d.notes)throw Error('Venda exige referência documental e confirmação comercial própria.');if(d.status==='teste'&&!d.patient)throw Error('Teste exige paciente sintético vinculado.');i.status=d.status;i.patient=d.patient||'';i.custody=d.custody;i.history.push(`${DEMO_DATE}: ${d.status} — ${d.notes||'movimento demonstrativo'}`);audit('Movimento de AASI fictício '+i.serial);break;}
case'inventory-form':{audit('Conferência de insumos fictícia '+d.name+' = '+d.count);break;}
case'gov-form':{state.tasks.unshift({id:uid('GOV'),name:`${d.type} · ${d.name}`,notes:d.notes});audit('Solicitação governança em memória');break;}
case'service-form':{state.services.push({id:uid('SV'),name:d.name,duration:Number(d.duration)||60,price:d.price?moneyInput(d.price):null});audit('Serviço fictício adicionado ao catálogo');break;}
case'hr-form':{state.hr.unshift({id:uid('RH'),person:d.person,category:d.category,notes:d.notes,status:'em triagem',reviewer:'Responsável por categoria'});audit('Protocolo RH demonstrativo');break;}
case'notice-form':{if(!permissions())throw Error('Somente gestão simulada publica avisos da clínica.');state.notices.unshift({id:uid('AV'),title:d.title,body:d.body,scope:d.scope,date:DEMO_DATE});audit('Aviso fictício criado para a equipe');break;}
case'rate-form':{let p=state.people.find(p=>p.id===d.id),rate=d.rate===''?null:pct(d.rate);if(!p||rate!==null&&(rate<0||rate>100))throw Error('Percentual inválido');p.rate=rate;p.notes=d.notes;p.base='pendente';audit('Regra de repasse alterada em simulação sem validação contratual');break;}
case'credit-form':{const st=state.stone.find(x=>x.id===d.id),credit=moneyInput(d.credit);if(!st||st.fee===null)throw Error('Taxa ainda não configurada');if(credit<0)throw Error('Valor negativo');if(st.credit!==null)throw Error('Crédito desta venda já confirmado; não duplicar');st.credit=credit;st.status=credit===st.expected?'conciliado':'divergencia';st.account=d.account;st.notes=d.notes;st.creditDate=d.date;state.tx.push({id:uid('FIN'),kind:'entrada',desc:'Depósito Stone '+st.id,patient:'',service:'',professional:'',gross:st.gross,fees:st.fee+st.advance,net:credit,account:d.account,method:'stone',status:'liquidado',date:d.date,due:d.date,paid:d.date,owner:state.role,source:st.id});audit('Crédito Stone registrado uma única vez, preservando tarifa original');break;}
case'ocr-form':{const file=f.querySelector('input[type=file]').files[0];toast(file?`Arquivo local reconhecido: ${file.name}. Nenhum OCR executado.`:'Nenhum arquivo selecionado');closeModal();return;}
default:return;
}closeModal();toast('Exemplo atualizado nesta sessão, sem envio a servidor.');render();}catch(err){toast('Verifique: '+err.message);console.warn('Validação demonstrativa:',err.message)}}
function showMessage(title,body){const elem=document.createElement('div');elem.id='active-modal';elem.className='modal-overlay';elem.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="row space"><h2>${esc(title)}</h2>${btn('✕','modal-close','small')}</div><div>${body}</div><div class="formfoot">${btn('Fechar','modal-close','primary')}</div></div>`;document.body.appendChild(elem)}
function act(a){if(!a)return;if(sessionStorage.getItem('SGI_RC8_DEV_LOGIN')!=='yes')return;const [name,...rest]=a.split(':'),arg=rest.join(':');
if(name==='logout'){sessionStorage.removeItem('SGI_RC8_DEV_LOGIN');state.app='home';render();return}
if(name==='support'){go('support','inicio');return}
if(name==='entity'){entityDetails(arg);return}
if(name==='entity-link'){linkEntityForm(arg);return}
if(name==='entity-toggle'){let p=extra.records.find(x=>x.id===arg);if(p){p.active=!p.active;audit('Estado cadastral alterado em demo: '+p.id);render()}return}
if(name==='entity-repasses'){go('finance','repasses');return}
if(name==='gov-approve'){let g=extra.govRequests.find(x=>x.id===arg);if(g){g.status='aprovado institucionalmente · convite não enviado';audit('Aprovação institucional simulada '+g.id);render();toast('Aprovado na demo. Nenhum usuário real foi ativado.')}return}
if(name==='gov-detail'){let g=extra.govRequests.find(x=>x.id===arg);if(g)showMessage('Solicitação '+g.id,`<p>Tipo: ${esc(g.type)}<br>Solicitante: ${esc(g.subject)}<br>Escopo: ${esc(g.scope)}<br>Estado: ${esc(g.status)}</p><p>Acesso verdadeiro exige autorização do backend e licenciamento.</p>`);return}
if(name==='budget-issue'){let b=extra.budgets.find(x=>x.id===arg);if(b&&b.status==='rascunho'){b.status='emitido';audit('Orçamento demonstrativo emitido '+b.id);render()}return}
if(name==='budget-accept'){let b=extra.budgets.find(x=>x.id===arg);if(b&&b.status==='emitido'){b.status='aceito';audit('Aceite comercial declarado em demo '+b.id);render()}return}
if(name==='budget-preview'){let b=extra.budgets.find(x=>x.id===arg);if(b)showMessage('Orçamento · '+b.id,`<p>Cliente: <b>${esc(entityName(b.person))}</b></p>${b.items.map(i=>`<p>${esc(i.label)} · ${i.qty}× ${brl(i.amount)}</p>`).join('')}<p>Desconto ${brl(b.discount)} · <b>Total ${brl(b.total)}</b></p><p>${esc(b.terms)}</p>${badge(b.status)}<div class="row">${btn('Imprimir','print:'+b.id)}${b.status==='emitido'?btn('Registrar aceite fictício','budget-accept:'+b.id,'primary'):''}${b.status==='aceito'&&!b.charge?btn('Preparar cobrança','budget-charge:'+b.id,'primary'):''}</div>`);return}
if(name==='budget-charge'){let b=extra.budgets.find(x=>x.id===arg);if(!b||b.charge||b.status!=='aceito'){toast('O orçamento precisa estar aceito e sem cobrança vinculada.');return}let tx={id:uid('FIN'),kind:'entrada',desc:'Orçamento '+b.id,patient:b.person,service:'',professional:b.owner||'',category:'',gross:b.total,fees:0,net:b.total,account:'cx-pj',date:DEMO_DATE,due:DEMO_DATE,paid:'',method:'a definir',status:state.role==='recepcao'?'aguardando validacao':'previsto',owner:state.role,source:b.id};state.tx.push(tx);b.charge=tx.id;audit('Cobrança proposta a partir de orçamento '+b.id+' sem crédito bancário');closeModal();go('finance','lancamentos');toast('Cobrança demonstrativa preparada, ainda não recebida.');return}
if(name==='file-preview'){let f=extra.files.find(x=>x.id===arg);if(f)showMessage('Documento fictício · '+f.id,`<p>${esc(f.type)} · ${esc(entityName(f.person))}</p><p>${esc(f.notes)}</p><p>Versão ${f.version} · ${badge(f.status)}</p><p>Sem assinatura nem validade clínica.</p>`);return}
if(name==='tour-next'){const total=(helpGuides[extra.guideId]||[]).length;extra.guideIndex=(extra.guideIndex+1)%total;render();return}
if(name==='tour-back'){extra.guideIndex=Math.max(0,extra.guideIndex-1);render();return}
if(name==='kit-xlsx'){exportContingencyXLSX();toast('Modelo Excel .xlsx demonstrativo gerado.');return}
if(name==='contingency-approve'){const r=extra.contingency.find(x=>x.code===arg);if(!r||r.status!=='em conferência')return;if(r.type==='fila'||r.type==='atendimento'){r.status='histórico conferido — sem alterar fila ativa';}else if(['entrada','saida'].includes(r.type)){r.status='revisão financeira pendente — sem alterar caixa';}else r.status='referência histórica conferida';audit('Conferência de contingência '+r.code);render();toast('Conferido como referência, sem movimentar fila ou caixa.');return}
if(name==='marketing-draw'){captureMarketingControls();drawMarketing();saveDemo();return}
if(name==='marketing-export'){captureMarketingControls();drawMarketing();let c=$('#marketing-canvas');if(c)c.toBlob(blob=>{if(blob)download(blob,'SGI_Audio_Arte_MARKETING_DEMO.png')},'image/png');return}
if(name==='marketing-help'){showMarketingHelp();return}
if(name==='marketing-tip'){showMessage('Assistente de Marketing · Orientação',`<p>${esc(marketingTips[arg]||'Dica não localizada.')}</p>${btn('Mais assuntos','marketing-help','small')}`);return}
if(name==='print'){printDocument(arg);return}
if(name==='dismiss-feedback'){state.feedback=null;render();return}if(name==='home'){go('home');return}if(name==='open'){go(arg);return}if(name==='nav'){go(state.app,arg);return}if(name==='theme'){state.theme=state.theme==='light'?'dark':'light';render();return}if(name==='modal'){openModal(arg.split(':')[0],arg.split(':').slice(1).join(':'));return}if(name==='modal-close'){closeModal();return}if(name==='finance-reset'){state.draft=null;state.review=false;state.advanced=false;go('finance','lancamentos');return}if(name==='finance-prev'){state.step=Math.max(1,state.step-1);render();return}
if(name==='finance-edit'){state.review=false;render();return}
 if(name==='set-operation'){state.draft={kind:arg,statusType:arg==='entrada'?'recebido':'apagar',date:DEMO_DATE,due:DEMO_DATE,first:DEMO_DATE,method:'pix',account:'cx-pj',installments:'1',interest:'0'};state.review=false;state.advanced=false;render();return}
 if(name==='bi-clear'){state.biMonth='all';render();return}
 if(name==='bi-month'){state.biMonth=arg;go('finance','analises');return}
 if(name==='bi-explain'){const el=$('#bi-drawer');if(el){el.innerHTML=formulaDrawer(arg);el.hidden=false;el.scrollIntoView({behavior:'smooth',block:'nearest'});}return}
 if(name==='close-drawer'){const el=$('#bi-drawer');if(el)el.hidden=true;return}
 if(name==='bulk-clear'){state.selectedTx=[];render();return}
 if(name==='bulk-review'){
  if(!permissions())return toast('Esta ação exige a Dra. Simone.');
  const eligible=state.tx.filter(t=>state.selectedTx.includes(t.id)&&(arg==='approve'?t.status==='aguardando validacao':t.status==='previsto'&&!t.planPending&&t.kind!=='transferencia'));
  showMessage('Confirmar ação em lote',`<p><b>${eligible.length} lançamento(s)</b> elegível(is) para ${arg==='approve'?'aprovação':'liquidação'} nesta demonstração.</p><p>Valor somado: <b>${brl(eligible.reduce((a,t)=>a+t.net,0))}</b>.</p><p>Itens incompatíveis serão ignorados. Aprovação não significa liquidação.</p>${btn('Confirmar operação','bulk-confirm:'+arg,'primary')}`);return;
 }
 if(name==='bulk-confirm'){
  if(!permissions())return;
  let n=0;for(const t of state.tx.filter(t=>state.selectedTx.includes(t.id))){
   if(arg==='approve'&&t.status==='aguardando validacao'){applyApproval(t);n++}
   if(arg==='settle'&&t.status==='previsto'&&!t.planPending&&t.kind!=='transferencia'){t.status='liquidado';t.paid=DEMO_DATE;audit('Liquidação lote '+t.id);n++}
  }
  state.selectedTx=[];closeModal();state.feedback={title:'Operação em lote conferida',body:`${n} registro(s) processado(s) somente em memória.`};render();return;
 }
 if(name==='execute-transfer'){
  if(!permissions())return toast('Somente gestora simulada pode executar transferências.');const t=state.tx.find(t=>t.id===arg);
  if(!t||t.status!=='aprovado'||t.kind!=='transferencia')return toast('Transferência não está autorizada ou já foi executada.');
  state.transfers.push({id:uid('TRF'),from:t.account,to:t.to,value:t.net,date:t.date});t.status='concluido';audit('Transferência solicitada autorizada e executada uma vez');render();return;
 }
 if(name==='lab-reset'){
  if(state.role!=='dev')return toast('Reinício reservado ao DEV demonstrativo.');
  if(!confirm('Reiniciar TODOS os dados fictícios desta demonstração? Essa ação não pode ser desfeita.'))return;
  localStorage.removeItem('SGI_RC8_DEMO_STATE');location.reload();return;
 }
 if(name==='notices'){showMessage('Avisos e tarefas demonstrativas',state.notices.map(n=>`<div class="task"><div class="detail"><b>${esc(n.title)}</b><p>${esc(n.body)} · Escopo ${esc(n.scope)}</p></div></div>`).join('')+(permissions()?btn('＋ Publicar aviso','modal:notice'):'')+`<p class="tiny">Nenhuma mensagem é enviada para pessoas reais.</p>`);return}
if(name==='mobile-menu'){showMessage('Navegação do aplicativo',(menus[state.app]||[]).map(([id,l])=>`<button class="navbtn" style="color:var(--ink);background:var(--surface2);margin:4px 0" data-act="nav:${id}">${esc(l)}</button>`).join(''));return}
if(name==='approve'){if(!permissions())return toast('Somente a Dra. Simone aprova solicitações da recepção nesta demonstração.');let t=state.tx.find(x=>x.id===arg);if(t&&t.status==='aguardando validacao'){applyApproval(t);audit('Rascunho '+arg+' aprovado pela Dra. Simone; sem liquidação');render();toast('Aprovado como lançamento previsto, sem liquidação.')}return}
if(name==='settle'){if(!permissions())return toast('Confirmação financeira exige permissão simulada da direção.');let t=state.tx.find(x=>x.id===arg);if(t&&t.status==='previsto'&&!t.planPending){t.status='liquidado';t.paid=DEMO_DATE;audit('Liquidação fictícia do lançamento '+arg);render();toast('Liquidação simulada registrada.')}return}
if(name==='detail'){const t=state.tx.find(x=>x.id===arg);if(t&&(safeFinanceAccess()||t.owner===state.role)){const detailRows=[['Tipo',t.kind],['Estado',t.status],['Bruto',brl(t.gross)],['Taxas',brl(t.fees)],['Líquido',brl(t.net)],['Data',dateBR(t.date)],['Vencimento',dateBR(t.due)],['Baixa',dateBR(t.paid)],['Fonte',t.source]].map(([k,v])=>`<div class="row space" style="padding:6px;border-bottom:1px solid var(--border)"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');showMessage('Detalhes do lançamento '+t.id,`<p><b>${esc(t.desc)}</b></p>`+detailRows+note('Aprovação e liquidação permanecem separadas. Dados e histórico são fictícios.'));}return}
if(name==='pay-ob'){if(!permissions())return toast('Operação exige autorização da direção simulada.');const o=state.obligations.find(x=>x.id===arg);if(o&&o.status==='previsto'){o.status='liquidado';o.paid=DEMO_DATE;state.tx.push({id:uid('FIN'),kind:'saida',desc:'Pagamento parcela '+o.name,patient:'',service:'',professional:'',gross:o.value,fees:0,net:o.value,account:o.account,method:'pix',status:'liquidado',date:DEMO_DATE,due:o.due,paid:DEMO_DATE,owner:state.role,source:o.id});audit('Obrigação liquidada uma vez '+arg);render();toast('Parcela liquidada somente no simulador.')}return}
if(name==='generate'){const r=state.recurring.find(x=>x.id===arg);if(r){let due=nextMonths('2026-11-01',0,r.day);if(state.obligations.some(o=>o.recurring===r.id&&o.due===due))return toast('A ocorrência da competência já existe.');state.obligations.push({id:uid('PAR'),name:r.name,value:r.value,due,account:r.account,status:'previsto',recurring:r.id});audit('Ocorrência recorrente prevista sem duplicar');render();toast('Competência demonstrativa gerada.')}return}
if(name==='reconcile'){const s=state.stone.find(x=>x.id===arg);if(!s||s.fee===null)return toast('Tarifa pendente: informe taxa manual autorizada.');if(s.credit!==null)return toast('Crédito já registrado: divergência será mantida até análise.');openModal('credit',arg);return}
if(name==='record'){let p=state.patients.find(x=>x.id===arg);if(p)showMessage('Linha do tempo sintética · '+p.name,`<p><b>${esc(p.id)}</b> · uma identidade, múltiplos eventos</p><div class="task"><div class="detail"><b>Cadastro administrativo</b><p>Contatos, representação e dados necessários aos serviços.</p></div></div><div class="task"><div class="detail"><b>Atendimentos</b><p>${state.intakes.filter(i=>i.patient===p.id).length} evento(s) demonstrativos nesta sessão.</p></div></div><div class="task"><div class="detail"><b>Prontuário</b><p>Não implementado: assinaturas, exames e evoluções clínicas válidas permanecem fora do escopo demo.</p></div></div>`);return}
if(name==='new-intake'){state.intakes.push({id:uid('ATD'),patient:arg,professional:'marcia',type:'avulso',date:DEMO_DATE,status:'em espera',notes:'Atendimento avulso fictício'});audit('Atendimento sintético aberto');go('patients','fila');return}
if(name==='intake-next'){let i=state.intakes.find(x=>x.id===arg);if(i){const flow=['em espera','chamado','em atendimento','concluido'];let index=flow.indexOf(i.status);if(index===2&&state.role==='recepcao')return toast('A recepção não conclui ato clínico.');i.status=flow[Math.min(flow.length-1,index+1)];audit('Fluxo operacional '+i.id+' → '+i.status);render();}return}
if(name==='checkin'){let x=state.appointments.find(a=>a.id===arg);if(x){x.status='chegada registrada';if(!state.intakes.some(i=>i.appointment===x.id))state.intakes.push({id:uid('ATD'),appointment:x.id,patient:x.patient,professional:x.professional,date:x.date,type:'agendado',status:'em espera',notes:'Check-in de agenda demonstrativa'});audit('Check-in sem início clínico nem liquidação');render();toast('Check-in registrado em memória.')}return}
if(name==='request-encaixe'){let x=state.appointments.find(a=>a.id===arg);if(x){x.status='solicitacao de encaixe';audit('Encaixe solicitado; depende da profissional');render();toast('Solicitação criada, sem reservar novo horário.')}return}
if(name==='stock-detail'){let x=state.inventory.find(i=>i.id===arg);if(x)showMessage('Histórico do AASI '+x.serial,`<p>${esc(x.model)} · ${esc(x.ownership)}</p>${x.history.map(s=>`<div class="task"><div class="detail">${esc(s)}</div></div>`).join('')}<p class="tiny">Documento, estoque e financeiro têm confirmação própria.</p>`);return}
if(name==='preview-template'){showMessage('Modelo de documento — '+arg,`<p><b>CLÍNICA ÁUDIO S.A. · MODELO FICTÍCIO</b></p><p>Documento de demonstração com campos de paciente, profissional, aparelho e data. Necessita validação jurídica/profissional, assinatura e infraestrutura de guarda antes de uso real.</p>`);return}
if(name==='preview-doc'){const x=state.documents.find(d=>d.id===arg);if(x)showMessage('Prévia não assinada',`<div class="card"><h3>${esc(x.type)}</h3><p>Paciente sintético: ${esc(person(x.patient))}</p><p>Equipamento: ${esc(x.serial)}</p><p>Versão: ${esc(x.version)}</p>${badge(x.status)}<p class="tiny">Documento sem assinatura e sem efeito físico/financeiro.</p></div>`);return}
if(name==='export'){try{if(arg==='xlsx')exportXLSX();else exportPDF();toast('Relatório fictício gerado para download.');}catch(err){console.error(err);toast('Erro na exportação: '+err.message)}return}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;if(el.closest('#active-modal')&&el.dataset.act.startsWith('nav:'))closeModal();if(el.closest('#active-modal')&&el.dataset.act==='modal:notice')closeModal();act(el.dataset.act)});
document.addEventListener('submit',handleSubmit);
document.addEventListener('change',e=>{
if(e.target.id==='dev-show-pass'){const pass=$('#dev-pass');if(pass)pass.type=e.target.checked?'text':'password';return}
if(e.target.id==='entityfilter'){extra.entityFilter=e.target.value;render();return}
if(e.target.id==='training-type'){extra.guideId=e.target.value;extra.guideIndex=0;render();return}
if(e.target.id==='marketing-style'){captureMarketingControls();render();return}
if(e.target.id==='contingency-xlsx'){importKitXLSX(e.target.files?.[0]).catch(err=>toast('Kit: '+err.message));return}
if(e.target.id==='marketing-image'){let file=e.target.files?.[0];if(file&&file.type.startsWith('image/')&&file.size<10*1024*1024){if(extra.imageUrl)URL.revokeObjectURL(extra.imageUrl);extra.imageUrl=URL.createObjectURL(file);extra.imageEl=new Image();extra.imageEl.onload=drawMarketing;extra.imageEl.src=extra.imageUrl;}else toast('Selecione imagem PNG/JPEG/WEBP com até 10 MB.');return}
if(e.target.id==='role'){state.role=e.target.value;state.draft=null;state.review=false;state.step=1;if(state.app==='finance'&&!safeFinanceAccess())state.page='lancamentos';if(state.app==='lab'&&state.role!=='dev'){state.app='home';state.page='';}render();toast('Perfil de interface alterado somente na simulação.');}if(e.target.id==='report-filter'){state.filter=e.target.value;render();}if(e.target.id==='bi-month'){state.biMonth=e.target.value;render();}if(e.target.matches('[data-txselect]')){const id=e.target.dataset.txselect;state.selectedTx=e.target.checked?[...new Set([...state.selectedTx,id])]:state.selectedTx.filter(x=>x!==id);}if(e.target.closest('#finance-entry')&&['method'].includes(e.target.name)){const f=e.target.closest('form');state.draft={...(state.draft||{}),...getForm(f),kind:state.draft?.kind||'saida'};state.review=false;render();}});
document.addEventListener('toggle',e=>{if(e.target.id==='advanced-finance')state.advanced=e.target.open;},true);
document.addEventListener('input',e=>{if(e.target.id==='f-entitysearch'){extra.entityQuery=e.target.value;const st=e.target.selectionStart;render();const nf=$('#f-entitysearch');nf?.focus();try{nf?.setSelectionRange(st,st)}catch(e){}return}if(['f-marketing-text','f-marketing-zoom','f-marketing-x','f-marketing-y'].includes(e.target.id)){captureMarketingControls();drawMarketing();return} const f=e.target.closest('#finance-entry');if(f&&e.target.name){state.draft={...(state.draft||{}),...getForm(f),kind:state.draft?.kind||'saida'};}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
// ---- Excel .xlsx real e autocontido: ZIP STORE + Open XML, sem CDN e sem CSV disfarçado. ----
const asBytes=s=>new TextEncoder().encode(s);const xesc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const crcTable=(()=>{let t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
function crc32(data){let crc=0xffffffff;for(let i=0;i<data.length;i++)crc=crcTable[(crc^data[i])&255]^(crc>>>8);return (crc^0xffffffff)>>>0}
function zipStore(entries){let local=[],central=[],offset=0;const u16=n=>[n&255,n>>>8&255],u32=n=>[n&255,n>>>8&255,n>>>16&255,n>>>24&255];for(const [fname,content] of entries){let name=asBytes(fname),data=typeof content==='string'?asBytes(content):content,crc=crc32(data);let header=Uint8Array.from([...u32(0x04034b50),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0)]);local.push(header,name,data);let centralHead=Uint8Array.from([...u32(0x02014b50),...u16(20),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset)]);central.push(centralHead,name);offset+=header.length+name.length+data.length;}const sizeCentral=central.reduce((s,c)=>s+c.length,0);const end=Uint8Array.from([...u32(0x06054b50),...u16(0),...u16(0),...u16(entries.length),...u16(entries.length),...u32(sizeCentral),...u32(offset),...u16(0)]);return new Blob([...local,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function sheetXML(headers,rows){let all=[headers,...rows.map(r=>headers.map(h=>r[h]??''))];return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="16"/><sheetData>${all.map((row,i)=>`<row r="${i+1}">${row.map((v,j)=>{let col='';let n=j+1;while(n){n--;col=String.fromCharCode(65+n%26)+col;n=Math.floor(n/26)}return `<c r="${col}${i+1}" t="inlineStr"><is><t>${xesc(v)}</t></is></c>`}).join('')}</row>`).join('')}</sheetData></worksheet>`}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function exportXLSX(){const rows=reportRows(),headers=['data','tipo','descricao','bruto','taxas','liquido','situacao','conta','paciente','profissional'];const entries=[['[Content_Types].xml',`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>`],['_rels/.rels',`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`],['xl/workbook.xml',`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Histórico financeiro" sheetId="1" r:id="rId1"/></sheets></workbook>`],['xl/_rels/workbook.xml.rels',`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`],['xl/worksheets/sheet1.xml',sheetXML(headers,rows)]];download(zipStore(entries),'SGI_Audio_Financeiro_DEMO.xlsx')}
// PDF básico personalizado (download real) apenas texto tabular sintético; impressão gráfica via navegador continua disponível.
function exportPDF(){const rows=reportRows(),report=financialTotals();let lines=[`SGI audiosa.app | Clínica Áudio S.A. | RELATÓRIO DEMONSTRATIVO`,`Data de referência: ${dateBR(DEMO_DATE)} | Origem: dados sintéticos | Não operacional`,`Saldo caixa: ${brl(report.cash)} | A receber: ${brl(report.pendingIncome)} | A pagar: ${brl(report.pendingOut)}`,'','DATA | TIPO | DESCRIÇÃO | LÍQUIDO | SITUAÇÃO',...rows.map(r=>`${r.data} | ${r.tipo} | ${r.descricao} | ${r.liquido} | ${r.situacao}`)];let streams=[];for(let i=0;i<lines.length;i+=40){let part=lines.slice(i,i+40),content=`BT /F1 10 Tf 46 793 Td 15 TL ${part.map((x,j)=>`${j?'T* ':''}(${pdfStr(x.slice(0,108))}) Tj`).join(' ')} ET`;streams.push(content)}let objects=[null,'<< /Type /Catalog /Pages 2 0 R >>',null,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>'];let pids=[];for(const stream of streams){const pageId=objects.length,streamId=objects.length+1;pids.push(pageId);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${streamId} 0 R >>`);objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`)}objects[2]=`<< /Type /Pages /Kids [${pids.map(i=>i+' 0 R').join(' ')}] /Count ${pids.length} >>`;let raw='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets.push(raw.length);raw+=`${i} 0 obj\n${objects[i]}\nendobj\n`}let start=raw.length;raw+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)raw+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;raw+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0)&255);download(new Blob([bytes],{type:'application/pdf'}),'SGI_Audio_Relatorio_DEMO.pdf')}
function pdfStr(s){return String(s).replace(/[\u2010-\u2015]/g,'-').replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/[^\x20-\xFF]/g,'?').replace(/([\\()])/g,'\\$1')}
loadDemo();for(const p of state.patients)if(!patientOptions.some(x=>x[0]===p.id))patientOptions.push([p.id,p.name]);for(const p of state.people)if(!profOptions.some(x=>x[0]===p.id))profOptions.push([p.id,p.name]);render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(err=>console.info('SW não instalado:',err.message));
